// The engine wiring: the hooks of ctx-mod. Everything that decides anything
// lives under `lib/`; this file only observes the engine, hands the events to a
// Session and answers. Phase 0's probe is kept under phase0/ as text: an event
// takes one unmatched hook per module, so the two cannot be loaded together.

import type { CommandRunResult, EngineInterface, Register, SessionCompactResult, SessionMessage } from 'claude-code'

import { formatArgs, isBackgroundRow, nonTextNote } from './lib/history.ts'
import { createSession, isHandoffText, looksLikePerson, stripInjected } from './lib/session.ts'
import type { AgentNote, Env, ImportedMessage, Io, Session } from './lib/session.ts'
import { describeFill, isCold, limitOf, shouldContinue } from './lib/usage.ts'
import { DEFAULTS, OWN_TOOL_PREFIX } from './lib/types.ts'

/** The section of the system prompt, the same all session long. */
const SYSTEM_TEXT =
  '这个会话可能跨多个上下文窗口。你有一个任务账本（mcp__ctx-mod__ledger_append、mcp__ctx-mod__ledger_read）和完整历史（mcp__ctx-mod__history）。工具结果末尾形如 [#123] 的是历史编号。每完成一个阶段，就追加一条账本记录：用 task_id 标识任务，status 填 in_progress / done / superseded / blocked。标 done 时必须在 evidence 里附上证明它的工具结果的历史编号。用户提出新请求时，如果它取代了旧任务，就把旧任务标为 superseded。对还没做完的任务，写明 next_step，并用 anchors 记下接下来要改的位置：文件路径，加一小段能在文件里唯一定位的原文。收到收尾或交接通知时，先更新账本。上下文用量可以用 mcp__ctx-mod__context 查看；它提示可以换窗口时，先记账再调用它的 new。申请换窗口之前，先用 ledger_append 把进行中任务的进度写清楚，text 里写明后面要用到的关键事实（产物路径、已确认的结论、约定的参数），有子代理在跑时写明各自的 id、负责什么、产物放哪。改法已经确定的改动不要留给新窗口：和 new 放在同一条消息里并发做完；只有还需要判断的才写进 anchors。'

/** Submitted after a switch the model itself asked for, so the new window carries on. */
const CONTINUE_TEXT = 'ctx-mod：已换到新的上下文窗口。先用一句话复述当前请求和进度，然后继续。'

const COMMAND = 'ctx-mod'
const PREFIX = OWN_TOOL_PREFIX
const KEEPER_CACHE = { plugin: 'cache-keeper', key: 'cache' } as const

/** How many main-thread tool calls are kept, to name a result's tool and input. */
const CALLS_KEPT = 200

/** A content block, structurally the engine's ApiContentBlock (which `claude-code` does not export). */
type Block = { type: string; [field: string]: unknown }

/** Whether the module acts at all: `CTX_MOD=1`, read at `session.start`. */
let enabled = false

/**
 * Why a window switch is under way, while one is: `'model'` (the model asked),
 * `'cold'` (a cold-cache prompt was held back), `'manual-switch'` (a person ran
 * `/ctx-mod switch`), null (a person's own compaction).
 */
let switchReason: string | null = null
/** Set by `session.compact` when this mod answered a compaction, so `turn.complete` sees it. */
let committed = false
/** Whether a held-prompt switch is under way: later prompts queue behind it instead of starting another. */
let isHoldingFlow = false
/** The next main-thread request is the first of a new window: note its prefix. */
let awaitingPrefix = false
// The main-loop step last counted as a request, so the same step seen twice counts once.
let lastStep: { turnId: string; index: number } | null = null

/** One Session per session id, over the files under that session's own directory. */
const sessions = new Map<string, Session>()
/** The compaction limit per session, computed once; a key present means it was asked for. */
const limits = new Map<string, number | undefined>()
/** The main thread's recent tool calls, by tool_use_id, to name a result's tool and input. */
// Prompts a person submitted and the conversation has not stored yet. The row
// the engine then appends does not always say who sent it (a headless
// session's own prompt arrives there as `unclassified`), so the submission,
// which does, is matched to its row by text.
const personTexts: string[] = []
// The last background row filed per door/name, so an unchanged repeat in the same window is not filed again.
const lastBackground = new Map<string, { window: number; text: string }>()
// An automatic compaction overtook a switch the model had been granted: the
// window is switched already, and the turn's end still owes the prompt to go on.
let continueAfterTurn = false
const calls = new Map<string, { tool: string; input: Record<string, unknown> }>()

const messageOf = (problem: unknown): string =>
  problem instanceof Error ? problem.message : String(problem)

const attempt = async <T>(run: () => Promise<T>, fallback: T): Promise<T> => {
  try {
    return await run()
  } catch {
    return fallback
  }
}

/** A failing hook logs and then walks the engine's own path, never the model's. */
const logError = ($: EngineInterface, where: string, problem: unknown): void => {
  try {
    $.ui.log(`ctx-mod: ${where}: ${messageOf(problem)}`, { to: 'debug' })
  } catch {
    // A log that fails must not become the failure.
  }
}

const idOf = async ($: EngineInterface): Promise<string | undefined> =>
  attempt(async () => await $.session.id(), undefined)

/** The longest input summary one history row carries, in characters. */
const MAX_BRIEF_CHARS = 300

/** How much of a SendMessage body a summary falls back to. */
const MESSAGE_HEAD = 120

const oneLine = (text: string): string => text.replace(/\s+/g, ' ').trim()

/**
 * A one-line summary of what a tool call was asked to do, so a later window can
 * find the call by its command or pattern instead of running the same probe
 * again. Only the tools whose result text never spells the call out are covered:
 * Read, Edit and Write already carry their path on the row.
 */
export const briefOf = (tool: string, input: Readonly<Record<string, unknown>>): string | undefined => {
  const str = (key: string): string | undefined => {
    const value = input[key]

    return typeof value === 'string' ? value : undefined
  }
  const clip = (text: string): string => {
    const flat = oneLine(text)

    return flat.length > MAX_BRIEF_CHARS ? flat.slice(0, MAX_BRIEF_CHARS) : flat
  }

  switch (tool) {
    case 'Bash':
    case 'PowerShell': {
      const command = str('command')

      return command === undefined ? undefined : clip(command)
    }
    case 'Grep':
    case 'Glob': {
      const pattern = str('pattern')
      if (pattern === undefined) return undefined
      const path = str('path')

      return clip(path === undefined ? pattern : `${pattern} in ${path}`)
    }
    case 'Agent': {
      const type = str('subagent_type')
      const description = str('description')
      if (type === undefined || description === undefined) return undefined

      return clip(`${type}: ${description}`)
    }
    case 'SendMessage': {
      const to = str('to')
      if (to === undefined) return undefined
      const body = str('summary') ?? str('message')

      return clip(body === undefined ? `to ${to}` : `to ${to}: ${body.slice(0, MESSAGE_HEAD)}`)
    }
    case 'ToolSearch':
    case 'WebSearch': {
      const query = str('query')

      return query === undefined ? undefined : clip(query)
    }
    case 'WebFetch': {
      const url = str('url')

      return url === undefined ? undefined : clip(url)
    }
    default:
      return undefined
  }
}

/**
 * The session's live agents as the handoff lists them. A listing that throws is
 * an empty one: a handoff without the subagents still beats no handoff at all.
 */
const agentsOf = async ($: EngineInterface): Promise<AgentNote[]> =>
  attempt(
    async () =>
      (await $.agent.list()).map(info => ({
        id: info.id,
        type: info.type,
        description: info.description,
        state: info.status,
      })),
    [],
  )

/** A tool use's arguments as a plain record, whatever shape the engine stored. */
const argsOfUse = (value: unknown): Readonly<Record<string, unknown>> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {}

/** One engine row as the lib's own shape; the tool name is `tool` there, not `name`. */
const importedOf = (message: SessionMessage): ImportedMessage => ({
  role: message.role,
  text: message.text,
  toolUses: message.toolUses.map(use => {
    const brief = briefOf(use.tool, argsOfUse(use.input))
    const args = formatArgs(argsOfUse(use.input))

    return {
      tool: use.tool,
      input: use.input,
      ...(typeof use.tool_use_id === 'string' && use.tool_use_id !== '' ? { callId: use.tool_use_id } : {}),
      ...(args === '' ? {} : { args }),
      ...(brief === undefined ? {} : { brief }),
      ...(use.text === undefined ? {} : { text: use.text }),
      ...(use.isError === true ? { isError: true as const } : {}),
    }
  }),
})

/**
 * Copies the conversation the engine already holds into a session the mod is
 * seeing for the first time: without it a session that predates the mod has
 * nothing on disk to hand over.
 */
const importOldConversation = async ($: EngineInterface, session: Session): Promise<void> => {
  try {
    const imported = await session.importMessages((await $.session.messages()).map(importedOf))
    if (imported > 0) $.ui.log(`ctx-mod: 补录了 ${imported} 条引擎对话里还没记录的行`, { to: 'debug' })
  } catch (error) {
    logError($, 'session.start messages', error)
  }
}

/** The most characters of a held message a notice quotes. */
const MAX_NOTICE_CHARS = 20_000

/** How the person is told a held message never entered: the lead line, then their own words. */
const unsentNotice = (lead: string, text: string): string =>
  text.length <= MAX_NOTICE_CHARS
    ? `${lead}${text}`
    : `${lead}${text.slice(0, MAX_NOTICE_CHARS)}（后面还有 ${text.length - MAX_NOTICE_CHARS} 个字符没有显示）`

const RESUBMIT_LEAD = 'ctx-mod：换窗口后没能重新提交你的消息，请重发：'
const LEFTOVER_LEAD = 'ctx-mod：上次换窗口时扣下的一条消息没有送达，请重发：'

/** Puts a system line in the conversation; false when it could not be shown. */
const tellPerson = async ($: EngineInterface, text: string): Promise<boolean> => {
  try {
    const stored = await $.session.append({
      message: { type: 'system', content: [{ type: 'text', text }] },
    })

    return stored.deny === undefined
  } catch (error) {
    logError($, 'prompt.submit notice', error)

    return false
  }
}

/**
 * Messages a earlier run held back and never got to submit again (a reload cancelled the
 * timer, or the process ended): told to the person, not re-sent, since how long ago they
 * were typed is unknown.
 */
const announceLeftovers = async ($: EngineInterface, session: Session): Promise<void> => {
  try {
    for (const item of session.heldItems()) {
      if (!(await tellPerson($, unsentNotice(LEFTOVER_LEAD, item.text)))) break
      await session.release(item.id)
    }
  } catch (error) {
    logError($, 'session.start held', error)
  }
}

/**
 * Submits the held messages again as the person's own, oldest first, until none is left (ones
 * held during the switch are in the same run). A message that did not enter is shown to the
 * person; when even that fails it stays on disk and the run stops, so it is not retried forever.
 */
const deliverHeld = async ($: EngineInterface, session: Session): Promise<void> => {
  for (;;) {
    const item = session.heldItems()[0]
    if (item === undefined) return
    let isDelivered = false
    try {
      const entered = await $.prompt.submit({ text: item.text, asUser: true })
      isDelivered = !(typeof entered === 'object' && entered !== null && 'drop' in entered)
      if (!isDelivered) logError($, 'prompt.submit resubmit', 'the re-submitted prompt was dropped')
    } catch (error) {
      logError($, 'prompt.submit resubmit', error)
    }
    // The person's words are gone unless the session says so.
    if (!isDelivered && !(await tellPerson($, unsentNotice(RESUBMIT_LEAD, item.text)))) return
    await session.release(item.id)
  }
}

/** The one session of this conversation, opened on first use. */
const sessionOf = async ($: EngineInterface): Promise<Session | undefined> => {
  const id = await idOf($)
  if (id === undefined) return undefined
  const held = sessions.get(id)
  if (held !== undefined) {
    await held.ready().catch(() => undefined)

    return held
  }

  const profile = await attempt(async () => await $.env.get('USERPROFILE'), undefined)
  const raw =
    typeof profile === 'string' && profile !== ''
      ? profile
      : await attempt(async () => await $.env.get('HOME'), undefined)
  const home = typeof raw === 'string' ? raw.replace(/[\\/]+$/, '') : ''
  // `$.fs` does not expand `~`: the data directory is built from the home path.
  const dir = home === '' ? `.claude/ctx-mod/${id}` : `${home}/.claude/ctx-mod/${id}`
  const io: Io = {
    read: path => $.fs.read(path),
    write: (path, text) => $.fs.write(path, text),
    exists: path => $.fs.exists(path),
    cwd: () => $.session.cwd(),
    now: () => Date.now(),
    // The names in a directory, for the cross-session measures: each session's own file is one of them.
    list: async path => (await $.fs.list(path)).filter(entry => entry.kind === 'file').map(entry => entry.name),
    onWriteError: (path, error) => logError($, `write ${path}`, error),
  }
  const session = createSession(dir, io, DEFAULTS)
  sessions.set(id, session)
  // The window, the ledger's freshness and the pending switch are read
  // synchronously: nobody gets the session before its state is off the disk.
  await session.ready().catch(() => undefined)
  // Only a session that has just been opened can be behind: a cached one has
  // seen every row through `session.append` already.
  await importOldConversation($, session)
  // Only on opening: a cached session's held messages belong to a switch still running.
  await announceLeftovers($, session)

  return session
}

/** The compaction threshold the engine reports, computed once per session. */
const limitFor = async ($: EngineInterface, id: string): Promise<number | undefined> => {
  if (!limits.has(id)) {
    limits.set(
      id,
      await attempt(async () => {
        const usage = await $.session.usage({ breakdown: 'summary' })

        return limitOf(usage.context.breakdown?.autoCompactThreshold, DEFAULTS)
      }, undefined),
    )
  }

  return limits.get(id)
}

/** The figures a decision reads, each one degrading to nothing rather than throwing. */
const envOf = async ($: EngineInterface, id: string): Promise<Env> => {
  const tokens = await attempt(async () => (await $.session.usage()).context.tokens, undefined)
  const fiveHourPercent = await attempt(
    async () => (await $.session.usage()).rateLimits.find(limit => limit.kind === 'five_hour')?.percentUsed,
    undefined,
  )
  const cache = await attempt(
    async () => (await $.state.get(KEEPER_CACHE)).value ?? null,
    null,
  )

  return {
    tokens,
    limit: (await limitFor($, id)) ?? limitOf(undefined, DEFAULTS),
    cache,
    fiveHourPercent,
  }
}

/** A person's own prompt: typed, bridged or an SDK host's, never a notification. */
// A tool call's arguments ride on `e` beside the engine's own keys: an argument
// named like one of those would be read as the envelope's, so they are taken off.
const ENVELOPE = ['tool', 'tool_use_id', 'consent', 'agentId', 'agent', 'requestMeta'] as const
const argsOf = (e: unknown): Readonly<Record<string, unknown>> => {
  const args: Record<string, unknown> = { ...(e as Record<string, unknown>) }
  for (const key of ENVELOPE) delete args[key]

  return args
}

const isPersonOrigin = (origin: { kind: string }): boolean =>
  origin.kind === 'composer' || origin.kind === 'bridge' || origin.kind === 'sdk'

/** A prompt this mod itself re-submitted as the person's own words. */
const isOurUser = (origin: { kind: string }): boolean => {
  const plugin = origin as { kind: string; name?: unknown; asUser?: unknown }

  return plugin.kind === 'plugin' && plugin.name === COMMAND && plugin.asUser === true
}

const textOf = (content: readonly Block[]): string =>
  content
    .filter(block => block.type === 'text' && typeof block.text === 'string')
    .map(block => String(block.text))
    .join('')

/** A tool_result block's text: the string itself, or its text blocks joined. */
const resultText = (content: unknown): string => {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return ''
  const parts: string[] = []
  for (const part of content) {
    if (typeof part === 'object' && part !== null && typeof (part as Block).text === 'string') {
      parts.push(String((part as Block).text))
    }
  }

  return parts.join('')
}

/**
 * The tools a ToolSearch result loaded: each tool_reference part names one. A part
 * whose name is not a string is skipped rather than guessed at.
 */
const toolReferencesOf = (content: unknown): string[] => {
  if (!Array.isArray(content)) return []
  const names: string[] = []
  for (const part of content) {
    if (typeof part !== 'object' || part === null) continue
    const ref = part as { type?: unknown; tool_name?: unknown }
    if (ref.type === 'tool_reference' && typeof ref.tool_name === 'string') names.push(ref.tool_name)
  }

  return names
}

const firstString = (
  input: Readonly<Record<string, unknown>>,
  keys: readonly string[],
): string | undefined => {
  for (const key of keys) {
    if (typeof input[key] === 'string') return input[key] as string
  }

  return undefined
}

/** The last 200 calls, so a result can name the tool and input it answers. */
const remember = (id: string, tool: string, input: Record<string, unknown>): void => {
  calls.set(id, { tool, input })
  while (calls.size > CALLS_KEPT) {
    const oldest = calls.keys().next()
    if (oldest.done === true) break
    calls.delete(oldest.value)
  }
}

/**
 * A `tool.call` matcher for one of this mod's own tools. The engine's tool-name
 * union is built from the tools connected when the types were generated, so a
 * name this mod registers itself does not appear there: the cast is the fix.
 */
const toolMatcher = (name: string): { tool: never } => ({ tool: name as never })

/** Refused on every one of this mod's tools: only the main conversation may call them. */
const AGENT_ONLY = { result: '这个工具只能由主会话调用。', isError: true as const }

/**
 * `/ctx-mod switch`: a window change a person asked for, with no model in the
 * loop. The compaction is asked for on a timer, as a held cold-cache prompt
 * asks for one, because a command hook may not run a command itself; nothing is
 * submitted after the switch, so the next thing the window carries is whatever
 * the person types.
 */
const manualSwitch = ($: EngineInterface, session: Session): CommandRunResult => {
  // A session a coordinator started has work to hand over before any person has spoken in it.
  if (session.latestPersonSeq() === null && session.latestRelaySeq() === null) {
    return { text: 'ctx-mod：还没有可交接的内容，不换窗口。' }
  }
  $.clock.after(300, () => {
    void (async () => {
      switchReason = 'manual-switch'
      try {
        await $.command.run({ command: 'compact' })
      } catch (error) {
        logError($, 'command.run switch', error)
        try {
          await $.session.append({
            message: {
              type: 'system',
              content: [{ type: 'text', text: 'ctx-mod：换窗口没有成功，上下文保持原样。' }],
            },
          })
        } catch (notice) {
          logError($, 'command.run notice', notice)
        }
      } finally {
        switchReason = null
      }
    })()
  })

  return { text: 'ctx-mod：正在换到新窗口（不调用模型）。' }
}

/**
 * Whether the call comes from a subagent. Read off the event itself: `argsOf`
 * takes the envelope's keys — `agentId` among them — off the arguments.
 */
const isSubagentCall = (e: unknown): boolean => (e as { agentId?: unknown }).agentId !== undefined

const TOOLS = [
  {
    name: 'context',
    description:
      '查看上下文用量，或申请换到新的上下文窗口。action 为 "new" 时申请换窗口；改法已经完全确定的改动，和 new 放在同一条消息里并发调用（如 ptc），让程序打印一行成败摘要，这些调用照常执行，摘要会完整带进交接；引擎批准后必须立即结束本回合，不要再发起新的工具调用。',
    inputSchema: {
      type: 'object',
      properties: {
        action: {
          type: 'string',
          enum: ['status', 'new'],
          description: '要做的事：status（默认）只报告用量；new 申请换窗口。',
        },
        reason: { type: 'string', description: '申请换窗口的原因（可选）。' },
        expect_more_work: {
          type: 'boolean',
          description: '换窗口后是否还有更多工作（可选，默认 true）。',
        },
      },
    },
  },
  {
    name: 'ledger_append',
    description:
      '向任务账本追加一条记录。每完成一个阶段就写一条：task_id 标识任务，status 取 in_progress / done / superseded / blocked，text 用一句话说明这一步（不能为空）。标 done 时必须在 evidence 里给出证明它的工具结果历史编号。对 in_progress 的任务必须写 next_step，并用 anchors 记下接下来要改的位置。next_step 和 anchors 省略表示沿用上一条（交接里会标明沿用自哪条），传空字符串或空数组表示清空。',
    inputSchema: {
      type: 'object',
      properties: {
        task_id: { type: 'string', description: '任务标识；同一个任务的多条记录用同一个 id。' },
        title: { type: 'string', description: '任务的一句话标题。' },
        status: {
          type: 'string',
          enum: ['in_progress', 'done', 'superseded', 'blocked'],
          description: '任务状态。',
        },
        text: { type: 'string', description: '这一步的要点，一句话。' },
        next_step: { type: 'string', description: '下一步要做什么（任务未完成时填写）。' },
        anchors: {
          type: 'array',
          description: '接下来要改的位置列表。',
          items: {
            type: 'object',
            properties: {
              path: { type: 'string', description: '文件路径。' },
              match: { type: 'string', description: '文件里能唯一定位的一小段原文。' },
              note: { type: 'string', description: '这个位置的说明。' },
            },
            required: ['path', 'match', 'note'],
          },
        },
        evidence: {
          type: 'array',
          items: { type: 'number' },
          description: '证明 done 的工具结果历史编号（形如 [#123] 里的数字）。',
        },
        superseded_by: { type: 'string', description: '取代它的任务 id（status 为 superseded 时填写）。' },
        request_ref: {
          type: 'number',
          description:
            '这条记录回应的请求的历史编号：用户亲口提的那条消息，或派发这个任务的那条转交（协调者、定时任务）。省略时用这两类里最近的一条，回执会写明对应到了哪一条。',
        },
      },
      required: ['task_id', 'title', 'status', 'text'],
    },
  },
  {
    name: 'ledger_read',
    description:
      '读取任务账本。view 可以是 home（默认，首页概览）、current（当前窗口的全部条目）或 archive:N（第 N 页归档）；给了 query 就在全部条目里搜索。',
    inputSchema: {
      type: 'object',
      properties: {
        view: { type: 'string', description: 'home、current 或 archive:N，默认 home。' },
        query: { type: 'string', description: '在 task_id、标题、正文和下一步里搜索的词。' },
      },
    },
  },
  {
    name: 'history',
    description:
      '检索或读取完整历史。action 为 "search" 时按条件查历史编号，为 "read" 时按编号读原文。工具结果末尾形的 [#123] 就是历史编号。读原文时 field 填 "input" 可以看到那次工具调用的完整参数（子代理的任务原文、发出的消息、完整的命令）。搜索默认不显示引擎自己塞进来的背景信息（附件、钩子上下文、备注）；要找它们就用 door 指定，如 "attachment"、"hook-context"、"note"。搜索不指定 window 时默认搜最近 3 个窗口；这几个窗口里没有命中会自动往更早的窗口找，找到有命中的窗口就停，结果末尾会写明实际搜了哪些窗口，没搜的窗口用 window 指定。命中只存在于被截断字段的原文时，结果会标出 [overflow text offset=N]（调用参数则标为 input），用 read 的 offset 从那里读全文。',
    inputSchema: {
      type: 'object',
      properties: {
        action: { type: 'string', enum: ['search', 'read'], description: 'search 或 read。' },
        query: { type: 'string', description: '搜索的词（search）。' },
        window: { type: 'number', description: '只看某个窗口（search）。' },
        role: { type: 'string', enum: ['user', 'assistant', 'tool'], description: '只看某种角色（search）。' },
        tool_name: { type: 'string', description: '只看某个工具的结果，填工具名如 Read（search）。' },
        path: { type: 'string', description: '只看某个文件（search）。' },
        door: {
          type: 'string',
          description: '只看从某个入口进来的行，如 delivery、attachment、hook-context、note、compaction、command；给了它，背景信息也会被搜到（search）。',
        },
        limit: { type: 'number', description: '最多返回多少条（search）。' },
        seq: { type: 'number', description: '要读的历史编号（read）。' },
        field: {
          type: 'string',
          enum: ['text', 'input'],
          description: 'text（默认）读结果正文；input 读那次工具调用的完整参数（read）。',
        },
        offset: { type: 'number', description: '从第几个字符开始读（read）。' },
        length: { type: 'number', description: '读多少个字符（read）。' },
      },
      required: ['action'],
    },
  },
] as const

// The instruction files (CLAUDE.md, AGENTS.md, memory) ride in the first user
// message, which has no cache mark, so every window writes them again. At the
// end of the system prompt they read from cache. The main system prompt is
// composed once per process and before the context is, so it carries the files
// as the previous process rendered them, kept on disk per working directory;
// the message drops its copy only when that text is the files as they are now.

/** The files as the previous process rendered them, read at session start. */
let storedClaudeMd: string | undefined
/** Where `storedClaudeMd` lives; empty when the mod is off for this session. */
let claudeMdPath = ''
/** The main system prompt carries `storedClaudeMd`. */
let claudeMdInSystem = false

/** Only the main conversation's prompt carries the files; a side analysis does not. */
const isMainCompose = (traits: readonly string[]): boolean => !traits.includes('analysis')

/** A file name for a working directory: a short hash, the same on every run. */
const cwdKey = (cwd: string): string => {
  let hash = 5381
  for (const char of cwd.replaceAll('\\', '/').toLowerCase()) hash = ((hash * 33) ^ char.charCodeAt(0)) >>> 0

  return hash.toString(16).padStart(8, '0')
}

/** The home directory from the environment; empty when neither variable names one. */
const homeOf = async ($: EngineInterface): Promise<string> => {
  const profile = await attempt(async () => await $.env.get('USERPROFILE'), undefined)
  const raw =
    typeof profile === 'string' && profile !== ''
      ? profile
      : await attempt(async () => await $.env.get('HOME'), undefined)

  return typeof raw === 'string' ? raw.replace(/[\\/]+$/, '') : ''
}

/** Reads the stored text at session start; off, or nothing stored, leaves it absent. */
const loadClaudeMd = async ($: EngineInterface, cwd: string): Promise<void> => {
  storedClaudeMd = undefined
  claudeMdInSystem = false
  claudeMdPath = ''
  if ((await $.env.get('CTX_MOD_CLAUDEMD_TO_SYSTEM')) === '0') return
  const home = await homeOf($)
  if (home === '') return
  claudeMdPath = `${home}/.claude/ctx-mod/claude-md/${cwdKey(cwd)}.txt`
  const text = await attempt(async () => await $.fs.read(claudeMdPath), undefined)
  storedClaudeMd = typeof text === 'string' && text.trim() !== '' ? text : undefined
}

// The process-stable attachments (the environment, the model, the listings) are
// asked again for the first request of every window, so every window writes
// them into the message again. Only the types every session in one directory
// can share (the listings and the whole texts) move to the end of the system
// prompt, where they read from cache; the session's own types (the environment
// with its scratchpad path, the model, the session context) stay in the
// message, so every session's prompt ends the same and another session's cache
// can be read. The main prompt is composed before they are asked: the texts
// seen are kept on disk under the session id, so a restart or resume of this
// session carries them from its first prompt. The shared types are also kept
// per entrypoint and working directory, so a new session there starts with the
// same prefix; the session archive, when there is one, wins. This process
// carries the texts it saw after a window switch.

/** The attachment types that stay the same for the process, so may move. */
const ATTACHMENT_TYPES: ReadonlySet<string> = new Set([
  'environment',
  'model',
  'output_style_instructions',
  'language',
  'agent_listing_delta',
  'mcp_instructions_delta',
  'skill_listing',
  'remote_session_change',
  'auto_mode',
  'session_context',
])

/** One process-stable attachment: its type and the text as the engine rendered it. */
type SeenAttachment = { type: string; text: string }

/** A stored entry's shape; anything else is a damaged archive. */
const isSeenAttachment = (item: unknown): item is SeenAttachment =>
  typeof item === 'object' &&
  item !== null &&
  typeof (item as { type?: unknown }).type === 'string' &&
  typeof (item as { text?: unknown }).text === 'string'

/** A type that may appear more than once: each delta and the listing is its own text. */
const isIncremental = (type: string): boolean => type === 'skill_listing' || type.endsWith('_delta')

/** The types every session in one directory may share: the listings and the whole texts. */
const SHARED_TYPES = [
  'skill_listing',
  'agent_listing_delta',
  'mcp_instructions_delta',
  'output_style_instructions',
  'language',
] as const

const SHARED_TYPE_SET: ReadonlySet<string> = new Set(SHARED_TYPES)
/** Types whose texts are lists of lines, so a change is compared line by line. */
const LIST_TYPE_SET: ReadonlySet<string> = new Set(['skill_listing', 'agent_listing_delta', 'mcp_instructions_delta'])
const SHARED_ORDER = new Map<string, number>(SHARED_TYPES.map((type, index): [string, number] => [type, index]))

/** The shared types first in their fixed order, then the rest in arrival order; the sort is stable. */
const orderedAttachments = (list: readonly SeenAttachment[]): SeenAttachment[] =>
  [...list].sort((a, b) => (SHARED_ORDER.get(a.type) ?? SHARED_TYPES.length) - (SHARED_ORDER.get(b.type) ?? SHARED_TYPES.length))

/** A listing's lines, without the empty ones and the trailing whitespace. */
const listingLines = (text: string): string[] =>
  text.split('\n').map(line => line.trimEnd()).filter(line => line !== '')

/**
 * What the message says for a listing the prompt already partly carries: the
 * new lines, and for a skill listing the lines this session lacks. Undefined
 * keeps the text as it came; null leaves it out of the message.
 */
const listingMessage = (type: string, text: string, inSystem: readonly SeenAttachment[]): string | null | undefined => {
  const same = inSystem.filter(seen => seen.type === type)
  if (same.length === 0) return undefined
  const lines = listingLines(text)
  const known = new Set(same.flatMap(seen => listingLines(seen.text)))
  const added = lines.filter(line => !known.has(line))
  // Almost no overlap: the whole text is new, so it reads better as it came.
  if (lines.length > 0 && added.length === lines.length) return undefined
  // Only a skill listing is a whole set; a delta is new lines by nature.
  const missing = type === 'skill_listing' ? [...known].filter(line => !lines.includes(line)) : []
  if (added.length === 0 && missing.length === 0) return null
  const parts: string[] = []
  if (added.length > 0) parts.push('In addition to what the system prompt lists:\n' + added.join('\n'))
  if (missing.length > 0) parts.push('These are no longer available in this session; ignore them:\n' + missing.join('\n'))

  return parts.join('\n\n')
}

/** Records one attachment; incremental types accumulate, the others keep only the newest per type. */
const recordAttachment = (type: string, text: string): boolean => {
  if (isIncremental(type)) {
    if (seenAttachments.some(seen => seen.type === type && seen.text === text)) return false
    seenAttachments.push({ type, text })

    return true
  }
  const index = seenAttachments.findIndex(seen => seen.type === type)
  if (index < 0) {
    seenAttachments.push({ type, text })

    return true
  }
  // A changed non-incremental text replaces the old one in place.
  if (seenAttachments[index]?.text === text) return false
  seenAttachments[index] = { type, text }

  return true
}

/** `CTX_MOD_ATTACH_TO_SYSTEM` is not 0: the whitelisted attachments may move. */
let attachToSystem = false
/** The whitelisted attachments the model read this process, in arrival order. */
let seenAttachments: SeenAttachment[] = []
/** The attachments the first window carries: this session's archive, else the shared one. */
let storedAttachments: SeenAttachment[] | undefined
/** Where the session archive lives; empty when the mod is off or the session has no id. */
let attachmentsPath = ''
/** The JSON last read or written for the session, so an unchanged list is not written again. */
let attachmentsSaved = ''
/** Where the working directory's shared archive lives; empty when the mod is off or home is unknown. */
let attachmentsSharedPath = ''
/** The shared archive's JSON last read or written; an empty list when there is none. */
let attachmentsSharedSaved = '[]'
/** The write in flight, so the next one starts after it. */
let attachmentsSaving: Promise<void> = Promise.resolve()
/** The entries the current main system prompt carries, so the message can leave them out or trim them. */
let attachmentsInSystem: SeenAttachment[] = []
/** A compaction happened: every main compose from now on carries the section. */
let attachmentsArmed = false

/** The entries in one archive; a damaged, empty or old string-array file is no archive. */
const readArchive = async ($: EngineInterface, path: string): Promise<SeenAttachment[] | undefined> => {
  const text = await attempt(async () => await $.fs.read(path), undefined)
  if (typeof text !== 'string') return undefined
  const parsed = await attempt(async () => JSON.parse(text) as unknown, undefined)
  if (!Array.isArray(parsed) || parsed.length === 0 || !parsed.every(isSeenAttachment)) return undefined

  return parsed as SeenAttachment[]
}

/** Reads the switch, this session's archive and the shared one at session start; a new process starts with nothing seen. */
const loadAttachments = async ($: EngineInterface, cwd: string): Promise<void> => {
  attachToSystem = (await $.env.get('CTX_MOD_ATTACH_TO_SYSTEM')) !== '0'
  seenAttachments = []
  storedAttachments = undefined
  attachmentsPath = ''
  attachmentsSaved = ''
  attachmentsSharedPath = ''
  attachmentsSharedSaved = '[]'
  attachmentsInSystem = []
  attachmentsArmed = false
  if (!attachToSystem) return
  const home = await homeOf($)
  if (home === '') return
  // The shared archive belongs to the working directory and the entrypoint: a
  // new session starts with the listings and whole texts another session there
  // already saw. The desktop app and the CLI list different skills, so each
  // keeps its own rather than overwriting the other's.
  const raw = await attempt(async () => await $.env.get('CLAUDE_CODE_ENTRYPOINT'), undefined)
  const entry = typeof raw === 'string' && /^[\w-]+$/.test(raw) ? raw : 'unknown'
  attachmentsSharedPath = home + '/.claude/ctx-mod/attachments/shared/' + entry + '-' + cwdKey(cwd) + '.json'
  const shared = await readArchive($, attachmentsSharedPath)
  const sharedEntries = shared?.filter(seen => SHARED_TYPE_SET.has(seen.type)) ?? []
  if (sharedEntries.length > 0) attachmentsSharedSaved = JSON.stringify(orderedAttachments(sharedEntries))
  // The session archive is this same conversation restarted, so it wins.
  const id = await idOf($)
  // The id names a file, so one that could leave the directory is not used.
  if (id !== undefined && /^[\w-]+$/.test(id)) {
    attachmentsPath = home + '/.claude/ctx-mod/attachments/' + id + '.json'
    const stored = await readArchive($, attachmentsPath)
    if (stored !== undefined) {
      storedAttachments = stored
      attachmentsSaved = JSON.stringify(stored)
    }
  }
  if (storedAttachments === undefined && sharedEntries.length > 0) storedAttachments = sharedEntries
}

/** Writes the texts seen so far back for the next process; an unchanged list is not written again. */
const saveAttachments = async ($: EngineInterface): Promise<void> => {
  // Attachments arrive in parallel: overlapping writes to one file leave it
  // padded with NULs, so each write waits for the one before and takes the
  // list as it is then.
  attachmentsSaving = attachmentsSaving.then(async () => {
    if (attachmentsPath !== '') {
      const text = JSON.stringify(seenAttachments)
      if (text !== attachmentsSaved) {
        try {
          await $.fs.write(attachmentsPath, text)
          attachmentsSaved = text
        } catch (error) {
          logError($, 'attachments', error)
        }
      }
    }
    if (attachmentsSharedPath !== '') {
      const shared = orderedAttachments(seenAttachments.filter(seen => SHARED_TYPE_SET.has(seen.type)))
      const text = JSON.stringify(shared)
      if (text !== attachmentsSharedSaved) {
        try {
          await $.fs.write(attachmentsSharedPath, text)
          attachmentsSharedSaved = text
        } catch (error) {
          logError($, 'attachments', error)
        }
      }
    }
  })
  await attachmentsSaving
}

/** After a window switch: the next main compose carries the attachments, so it is composed again. */
const armAttachments = ($: EngineInterface): void => {
  if (!attachToSystem) return
  attachmentsArmed = true
  attachmentsInSystem = []
  $.ui.invalidate('prompt.section')
}

export const register: Register = (on, options) => {
  // The context fires once per conversation and again after a compaction.
  on('prompt.context', async ($, e, next) => {
    const result = await next(e)
    if (!enabled || claudeMdPath === '') return result
    try {
      const block = result.blocks.find(b => b.name === 'claudeMd')
      const files = (result.instructionFiles ?? e.instructionFiles ?? []).filter(f => f.content.trim() !== '')
      if (block === undefined || files.length === 0) return result
      // The block is the files' whole rendering: the announcement and each file's contents.
      const current = block.text
      if (current !== storedClaudeMd) {
        // The next process composes with these; this one keeps its copy in the message.
        await $.fs.write(claudeMdPath, current)

        return result
      }
      // Only a main prompt already composed with this text lets the message drop its copy.
      if (!claudeMdInSystem) return result

      return { ...result, blocks: result.blocks.filter(b => b !== block) }
    } catch (error) {
      logError($, 'prompt.context', error)

      return result
    }
  })

  on('session.start', async ($, e, next) => {
    try {
      enabled = (await $.env.get('CTX_MOD')) === '1'
      if (enabled) {
        await loadAttachments($, e.cwd).catch(error => logError($, 'attachments', error))
        await loadClaudeMd($, e.cwd).catch(error => logError($, 'claude-md', error))
      }
      // The command is always there, so a person who installed the mod and
      // typed /ctx-mod is told how to turn it on instead of meeting an unknown command.
      await $.command.register({
        name: COMMAND,
        description: '显示 ctx-mod 的状态；/ctx-mod switch 立即换到新窗口（不调用模型）',
      })
      if (enabled) {
        for (const tool of TOOLS) {
          await $.tool.register({ ...tool, isDeferred: false })
        }
        await sessionOf($)
      }
    } catch (error) {
      logError($, 'session.start', error)
    }

    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e, next) => {
    if (!enabled) {
      return { text: 'ctx-mod 未启用：用环境变量 CTX_MOD=1 启动 Claude Code 后生效（例如 `CTX_MOD=1 claude`）。' }
    }
    try {
      const session = await sessionOf($)
      if (session === undefined) return { text: 'ctx-mod：拿不到会话。' }
      // `args` is absent on a bare `/ctx-mod`, and on a run whose arguments the
      // surface never carried.
      if (typeof e.args === 'string' && e.args.trim() === 'switch') return manualSwitch($, session)
      const id = await idOf($)
      const env = id === undefined ? undefined : await envOf($, id)
      const head = 'ctx-mod 已启用（CTX_MOD=1）。'

      return { text: env === undefined ? head : `${head}\n${session.status(env)}` }
    } catch (error) {
      logError($, 'command.run', error)

      return { text: `ctx-mod: ${messageOf(error)}` }
    }
  })

  on('prompt.compose', async ($, e, next) => {
    if (!enabled) return next(e)
    const result = await next(e)
    try {
      const main = isMainCompose(e.traits)
      const claudeMd = main && storedClaudeMd !== undefined
        ? [{ id: 'ctx-mod:claude-md', text: storedClaudeMd, scope: 'session' as const }]
        : []
      if (claudeMd.length > 0) claudeMdInSystem = true
      // The attachments ride after the files and before the mod's own section,
      // so the prompt's tail stays the same all window long. The order is fixed:
      // the shared types first, so every session in this directory starts with
      // the same prefix, then the rest as they arrived. Until a switch the
      // previous process's texts are used, so the first window hits the cache;
      // after one, this process's own texts replace them, dropping stale ones.
      // Only the shared types move: a session's own texts (its scratchpad path,
      // model, git status) would make every session's prompt differ, so the
      // prompt's tail could never be read from another session's cache.
      const attachmentsSource = orderedAttachments(attachmentsArmed ? seenAttachments : storedAttachments ?? [])
        .filter(seen => SHARED_TYPE_SET.has(seen.type))
      const attachments = main && attachToSystem && attachmentsSource.length > 0
        ? [{ id: 'ctx-mod:attachments', text: attachmentsSource.map(seen => seen.text).join('\n\n'), scope: 'session' as const }]
        : []
      // Only a main prompt carries them; a side analysis leaves the set alone.
      if (main) attachmentsInSystem = attachments.length > 0 ? attachmentsSource : []

      return {
        ...result,
        sections: [
          ...result.sections,
          ...claudeMd,
          ...attachments,
          { id: 'ctx-mod:context', text: SYSTEM_TEXT, scope: 'session' as const },
        ],
      }
    } catch (error) {
      logError($, 'prompt.compose', error)

      return result
    }
  })

  // The engine asks the process-stable attachments again for every window; once
  // the system prompt carries a text, the message leaves it out. A subagent's
  // attachments are its own and pass through.
  on('prompt.attachment', async ($, e, next) => {
    if (!enabled || !attachToSystem) return next(e)
    if (isSubagentCall(e)) return next(e)
    const result = await next(e)
    try {
      if (!ATTACHMENT_TYPES.has(e.type) || result.text === null) return result
      const text = result.text
      // Record first, with the whole text: a text the prompt carries, or that the
      // message only partly carries, must survive the next switch unchanged.
      if (recordAttachment(e.type, text)) await saveAttachments($)
      if (attachmentsInSystem.some(seen => seen.text === text)) return { text: null }
      // A listing the prompt partly carries: the message says only what is new,
      // and for a skill listing what the prompt lists but this session lacks.
      if (SHARED_TYPE_SET.has(e.type) && LIST_TYPE_SET.has(e.type)) {
        const message = listingMessage(e.type, text, attachmentsInSystem)
        if (message === null) return { text: null }
        if (message !== undefined) return { text: message }
      }

      return result
    } catch (error) {
      logError($, 'prompt.attachment', error)

      return result
    }
  })

  on('tool.call', { tool: 'mcp__ctx-mod__context' as never }, async ($, e, next) => {
    if (!enabled) return next(e)
    if (isSubagentCall(e)) return AGENT_ONLY
    const input = argsOf(e)
    try {
      const session = await sessionOf($)
      const id = await idOf($)
      if (session === undefined || id === undefined) return next(e)
      const env = await envOf($, id)

      return input.action === 'new'
        ? session.requestSwitch(input, env)
        : { result: `${session.status(env)}\n${session.historyWriteStats()}` }
    } catch (error) {
      logError($, 'tool.call context', error)

      return next(e)
    }
  })

  on('tool.call', { tool: 'mcp__ctx-mod__ledger_append' as never }, async ($, e, next) => {
    if (!enabled) return next(e)
    if (isSubagentCall(e)) return AGENT_ONLY
    const input = argsOf(e)
    try {
      const session = await sessionOf($)
      const id = await idOf($)
      if (session === undefined || id === undefined) return next(e)

      return await session.ledgerAppend(input, await envOf($, id))
    } catch (error) {
      logError($, 'tool.call ledger_append', error)

      return next(e)
    }
  })

  on('tool.call', { tool: 'mcp__ctx-mod__ledger_read' as never }, async ($, e, next) => {
    if (!enabled) return next(e)
    if (isSubagentCall(e)) return AGENT_ONLY
    const input = argsOf(e)
    try {
      const session = await sessionOf($)
      if (session === undefined) return next(e)

      return await session.ledgerRead(input)
    } catch (error) {
      logError($, 'tool.call ledger_read', error)

      return next(e)
    }
  })

  on('tool.call', { tool: 'mcp__ctx-mod__history' as never }, async ($, e, next) => {
    if (!enabled) return next(e)
    if (isSubagentCall(e)) return AGENT_ONLY
    const input = argsOf(e)
    try {
      const session = await sessionOf($)
      if (session === undefined) return next(e)

      return await session.historyTool(input)
    } catch (error) {
      logError($, 'tool.call history', error)

      return next(e)
    }
  })

  on('tool.call', async ($, e, next) => {
    if (!enabled) return next(e)
    if (e.agentId !== undefined) return next(e)
    // A tool of this mod's own is answered by its matcher above; this hook is
    // for everything else, and it runs after that one.
    if (String(e.tool).startsWith(PREFIX)) return next(e)
    try {
      remember(String(e.tool_use_id), String(e.tool), e as unknown as Record<string, unknown>)
      const session = await sessionOf($)
      if (session !== undefined && session.blocksCalls()) {
        return { deny: '正在换窗口：请立即结束本回合，不要再调用工具。' }
      }
      // A resume of an ended subagent whose cache has gone cold is held back once, with its cost.
      if (session !== undefined && String(e.tool) === 'SendMessage') {
        const args = argsOf(e)
        const to = typeof args.to === 'string' ? args.to : ''
        const message = typeof args.message === 'string' ? args.message : ''
        const notice = await session.coldResend(to, message)
        if (notice !== null) return { deny: notice }
        await session.agentResumed(to)
      }
      // A load that would rebuild the cache waits for a window switch while the context is large.
      if (session !== undefined && String(e.tool) === 'ToolSearch') {
        const id = await idOf($)
        const tokens = id === undefined ? undefined : (await envOf($, id)).tokens
        const refusal = session.gateLoad(argsOf(e).query, tokens)
        if (refusal !== null) return { deny: refusal }
      }
    } catch (error) {
      logError($, 'tool.call before', error)
    }

    const result = await next(e)
    try {
      const session = await sessionOf($)
      const id = await idOf($)
      if (session !== undefined && id !== undefined) {
        const env = await envOf($, id)
        const text = session.reminder(env)
        if (text !== null) {
          await $.session.append({
            message: { type: 'user', content: [{ type: 'text', text }] },
          })
        }
      }
    } catch (error) {
      logError($, 'tool.call after', error)
    }

    return result
  }).catch(($, e, next) => next(e))

  on('session.append', async ($, e, next) => {
    if (!enabled) return next(e)
    if (e.agentId !== undefined) return next(e)
    try {
      const session = await sessionOf($)
      if (session === undefined) return next(e)

      if (e.door === 'prompt') {
        const said = textOf(e.message.content)
        // The engine's own session-start hook lands in this door too, wrapped in
        // a `<system-reminder>` block: a person's row must survive stripping it
        // and still not look like an injected notice. The text held in
        // `personTexts` came from `prompt.submit`, which never sees that block,
        // so the match is made on the stripped text as well.
        const stripped = stripInjected(said)
        let at = personTexts.indexOf(said.trim())
        if (at === -1 && stripped !== '') at = personTexts.indexOf(stripped)
        if (at !== -1) personTexts.splice(at, 1)
        // With the source confirmed, only the engine's own envelopes are ruled out by their opening; any other `<` is the person's words.
        const isConfirmed = at !== -1 || isPersonOrigin(e.origin) || isOurUser(e.origin)
        const isPerson = isConfirmed && stripped !== '' && looksLikePerson(stripped, true)
        await session.record({
          uuid: e.uuid,
          role: 'user',
          ...(isPerson ? { isPerson: true as const } : {}),
          // Kept as the engine stamped it: a coordinator's hand-off is told by this, not by its words.
          origin: e.origin.kind,
          // The handoff a switch answers with comes back through this door, not `compaction`;
          // naming it lets a search by that door find what each window opened with.
          ...(isHandoffText(said) ? { door: 'compaction' } : {}),
          text: textOf(e.message.content),
        })

        return next(e)
      }

      if (e.door === 'response') {
        const text = textOf(e.message.content)
        if (text !== '') await session.record({ uuid: e.uuid, role: 'assistant', text })

        return next(e)
      }

      if (e.door === 'tool-result') {
        const out: Block[] = []
        for (const block of e.message.content) {
          if (block.type !== 'tool_result') {
            out.push(block)
            continue
          }
          const callId = String(block.tool_use_id ?? '')
          const found = calls.get(callId)
          const tool = found?.tool ?? (e.origin.kind === 'tool' ? e.origin.tool : 'unknown')
          const input = found?.input ?? {}
          const isError = block.is_error === true
          const path = firstString(input, ['file_path', 'notebook_path', 'path'])
          const brief = briefOf(tool, input)
          // `input` is the whole call event; the arguments are what is left once the envelope is off.
          const args = found === undefined ? '' : formatArgs(argsOf(found.input))
          // A ToolSearch result names the deferred tools it loaded; the next window
          // is told which of them were used, so it can load them in its first step.
          const loaded = tool === 'ToolSearch' ? toolReferencesOf(block.content) : []
          const text = resultText(block.content)
          // Whatever is not text (an image, a document) must not vanish without a trace.
          const note = nonTextNote(Array.isArray(block.content) ? block.content : [], loaded.length > 0 ? ['tool_reference'] : [])
          // A reference-only result has no text; name what it loaded so the row is not blank.
          const body = text === '' && loaded.length > 0 ? `已加载：${loaded.join('、')}` : text
          const record = await session.record({
            uuid: e.uuid,
            role: 'tool',
            tool,
            ...(path === undefined ? {} : { path }),
            ...(brief === undefined ? {} : { input: brief }),
            ...(args === '' ? {} : { args }),
            ...(callId === '' ? {} : { callId }),
            ...(isError ? { isError: true as const } : {}),
            ...(loaded.length === 0 ? {} : { loaded }),
            text: note === '' ? body : body === '' ? note : `${body}\n${note}`,
          })
          session.activity(tool, input, record.seq, isError)

          // This mod's own results are recorded, never numbered.
          // A result that carries anything but text (ToolSearch's tool
          // references, images) is refused by the API once text is mixed in.
          const isPlain =
            typeof block.content === 'string' ||
            (Array.isArray(block.content) &&
              block.content.every(part => (part as { type?: unknown }).type === 'text'))
          if (tool.startsWith(PREFIX) || !isPlain) {
            out.push(block)
            continue
          }
          const suffix = `[#${record.seq}]`
          out.push(
            typeof block.content === 'string'
              ? { ...block, content: `${block.content}\n${suffix}` }
              : {
                  ...block,
                  content: [...(Array.isArray(block.content) ? block.content : []), { type: 'text', text: suffix }],
                },
          )
        }

        return next({ ...e, message: { ...e.message, content: out } })
      }

      // Every other door: the row is kept when a request carries it, which is what `role` says.
      // A notice and the like have none and never reach the model, so they stay out.
      const role = e.message.role
      if (role !== undefined) {
        const body = textOf(e.message.content)
        const note = nonTextNote(e.message.content)
        const text = note === '' ? body : body === '' ? note : `${body}\n${note}`
        if (text !== '') {
          const name = e.message.name
          // A message the person typed mid-turn comes back as a queued_command attachment, wrapped in
          // text nobody has seen; the origin says `engine`, so it is told by the words they submitted.
          // The engine files it under `delivery`, not `attachment`: the name is what tells it.
          let said: string | undefined
          if ((e.door === 'attachment' || e.door === 'delivery') && name === 'queued_command') {
            const at = personTexts.findIndex(typed => typed !== '' && body.includes(typed))
            if (at !== -1) {
              const typed = personTexts.splice(at, 1)[0] ?? ''
              const stripped = stripInjected(typed)
              if (stripped !== '' && looksLikePerson(stripped, true)) said = typed
            }
          }
          // The engine injects the same background attachment on every request; one copy per window
          // shows what was injected then, and a repeat only burns a number and a shard rewrite.
          const isBackground = isBackgroundRow({ door: e.door, ...(name === undefined ? {} : { name }) })
          const backgroundKey = `${e.door}/${name ?? ''}`
          const window = session.window()
          const previous = lastBackground.get(backgroundKey)
          if (isBackground && previous !== undefined && previous.window === window && previous.text === text) {
            return next(e)
          }
          await session.record({
            uuid: e.uuid,
            role,
            ...(said === undefined ? {} : { isPerson: true as const }),
            door: e.door,
            ...(name === undefined ? {} : { name }),
            text: said ?? text,
          })
          if (isBackground) lastBackground.set(backgroundKey, { window, text })
        }
      }
    } catch (error) {
      logError($, 'session.append', error)
    }

    return next(e)
  })

  on('agent.spawn', async ($, e, next) => {
    if (!enabled) return next(e)
    const result = await next(e)
    try {
      const id = result.agentId
      // Only the main loop's own spawns are noted: a spawn from inside a subagent is
      // not one a new window can resume, and a fork carries the parent's conversation
      // rather than a task of its own.
      if (typeof id === 'string' && id !== '' && e.parentAgentId === undefined && e.fork !== true) {
        const session = await sessionOf($)
        await session?.noteAgent({
          id,
          type: e.subagentType,
          description: e.description,
          model: result.model,
          ...(typeof e.name === 'string' ? { name: e.name } : {}),
        })
      }
    } catch (error) {
      logError($, 'agent.spawn', error)
    }

    return result
  })

  // `turn.step` streams, so its hook is the generator the engine reads: every chunk
  // passes through untouched, and the recording reads only the result that comes back.
  on('turn.step', async function* ($, e, next) {
    if (!enabled) return yield* next(e)
    const result = yield* next(e)
    try {
      // Only the main loop's requests are measured: a subagent has a cache of its own.
      const usage = result.usage
      if (e.agentId !== undefined) {
        // A subagent's request size is the size a later resume would have to rewrite once its cache is gone.
        if (usage !== null) {
          const size =
            (typeof usage.input_tokens === 'number' ? usage.input_tokens : 0) +
            (typeof usage.cache_read_input_tokens === 'number' ? usage.cache_read_input_tokens : 0) +
            (typeof usage.cache_creation_input_tokens === 'number' ? usage.cache_creation_input_tokens : 0)
          await (await sessionOf($))?.agentStep(e.agentId, size)
        }
      } else {
        const session = await sessionOf($)
        // One step is one model request, whether or not it called a tool; a retried
        // or replayed step carries the same turn and index and is not a second one.
        const isNewStep = session !== undefined && (lastStep === null || lastStep.turnId !== e.turnId || lastStep.index !== e.index)
        if (usage !== null) {
          const measured = {
            input: typeof usage.input_tokens === 'number' ? usage.input_tokens : 0,
            read: typeof usage.cache_read_input_tokens === 'number' ? usage.cache_read_input_tokens : 0,
            write: typeof usage.cache_creation_input_tokens === 'number' ? usage.cache_creation_input_tokens : 0,
          }
          await session?.noteStep(measured)
          // The first step after a switch carries the new window's whole prefix.
          if (session !== undefined && awaitingPrefix) {
            session.notePrefix(measured.input + measured.read + measured.write)
            awaitingPrefix = false
          }
        }
        // Refreshed only after noteStep, which judges the previous request's age and must still see it.
        if (session !== undefined && isNewStep) {
          lastStep = { turnId: e.turnId, index: e.index }
          session.noteRequest()
        }
      }
    } catch (error) {
      logError($, 'turn.step', error)
    }

    return result
  })

  on('turn.complete', async ($, e, next) => {
    if (!enabled) return next(e)
    if (e.agentId !== undefined) {
      // A subagent's own turn: its noted row is tagged as ended, which the handoff reads.
      try {
        const session = await sessionOf($)
        await session?.agentEnded(e.agentId)
      } catch (error) {
        logError($, 'turn.complete agent', error)
      }

      return next(e)
    }
    const result = await next(e)
    let session: Session | undefined
    try {
      session = await sessionOf($)
      const id = await idOf($)
      if (continueAfterTurn) {
        continueAfterTurn = false
        if (e.reason === 'answer' && id !== undefined) {
          const env = await envOf($, id)
          if (shouldContinue(env.fiveHourPercent, env.cache, DEFAULTS)) {
            await $.prompt.submit({ text: CONTINUE_TEXT })
          }
        }
      } else if (session !== undefined && session.pending() !== null) {
        if (e.reason !== 'answer') {
          session.clearPending()
        } else {
          switchReason = 'model'
          committed = false
          try {
            await $.command.run({ command: 'compact' })
          } catch (error) {
            // A compaction that threw committed nothing; the pending the model
            // was granted must still be cleared, or every call is refused.
            logError($, 'turn.complete compact', error)
          } finally {
            switchReason = null
          }
          if (!committed) {
            session.clearPending()
          } else if (id !== undefined) {
            const env = await envOf($, id)
            if (shouldContinue(env.fiveHourPercent, env.cache, DEFAULTS)) {
              await $.prompt.submit({ text: CONTINUE_TEXT })
            }
          }
        }
      }
    } catch (error) {
      logError($, 'turn.complete', error)
    } finally {
      // Every main turn ends by flushing, however the switch it may have started went.
      if (session !== undefined) {
        try {
          await session.flush()
        } catch (error) {
          logError($, 'turn.complete flush', error)
        }
      }
    }

    return result
  })

  on('session.compact', async ($, e, next) => {
    if (!enabled) return next(e)
    if (e.agentId !== undefined || e.trigger === 'precompute') return next(e)
    const mine = switchReason !== null && e.trigger === 'manual'
    let session: Session | undefined
    let env: Env | undefined
    let id: string | undefined
    try {
      id = await idOf($)
      session = await sessionOf($)
      if (id === undefined || session === undefined) return next(e)
      env = await envOf($, id)
      let isZeroSummary = mine || (e.trigger === 'auto' && session.canSkipSummary())
      if (isZeroSummary) {
        // A zero-summary switch drops the conversation on the promise that the files hold it, so that must be true.
        await session.flush()
        const unsaved = session.unsaved()
        if (unsaved.length > 0) {
          logError($, 'session.compact', `not on disk, so core summarizes instead: ${unsaved.join(', ')}`)
          isZeroSummary = false
        }
      }
      if (isZeroSummary) {
        // A zero-summary switch: this mod answers in place of core.
        if (!mine && session.pending() !== null) continueAfterTurn = true
        const text = await session.buildHandoff({
          isMidTurn: e.trigger === 'auto',
          agents: await agentsOf($),
        })
        await session.commitSwitch({
          trigger: mine ? switchReason ?? 'manual' : 'auto',
          tokensBefore: env.tokens,
          handoffText: text,
        })
        committed = true
        awaitingPrefix = true
        armAttachments($)

        return { messages: [{ role: 'user', text, toolUses: [] }] }
      }
    } catch (error) {
      logError($, 'session.compact before', error)

      return next(e)
    }

    const result: SessionCompactResult = await next(e)
    try {
      if (result.messages !== undefined && session !== undefined && env !== undefined) {
        // Core made a summary: keep it and append this mod's own handoff after.
        const text = await session.buildHandoff({
          isMidTurn: e.trigger === 'auto',
          agents: await agentsOf($),
        })
        await session.commitSwitch({
          trigger: e.trigger === 'auto' ? 'auto-summary' : 'manual',
          tokensBefore: env.tokens,
          handoffText: text,
        })
        // When the disk check sent a switch the model asked for down this path, `turn.complete` still has to see it happened.
        if (mine) committed = true
        awaitingPrefix = true
        armAttachments($)

        return { ...result, messages: [...result.messages, { role: 'user', text, toolUses: [] }] }
      }
    } catch (error) {
      logError($, 'session.compact after', error)
    }

    return result
  })

  on('prompt.submit', async ($, e, next) => {
    if (!enabled) return next(e)
    let holds = false
    let starts = false
    let isExpired = false
    let heldSession: Session | undefined
    let heldIdOf = 0
    try {
      const session = await sessionOf($)
      const id = await idOf($)
      if (
        session !== undefined &&
        id !== undefined &&
        isPersonOrigin(e.origin) &&
        (e.attachments?.length ?? 0) === 0
      ) {
        // During a switch every such message waits its turn; otherwise only a cold cache holds one.
        let wants = isHoldingFlow
        if (!wants) {
          const env = await envOf($, id)
          wants =
            env.tokens !== undefined &&
            env.tokens >= DEFAULTS.coldMinTokens &&
            isCold({ now: Date.now(), cache: env.cache, lastRequestAt: session.lastRequestAt() }, DEFAULTS)
          isExpired = wants
        }
        // Held only once it is on disk: a message that could not be saved goes in as usual.
        const heldId = wants ? await session.hold(e.text) : null
        if (heldId !== null) {
          holds = true
          heldSession = session
          heldIdOf = heldId
          // Decided after the awaits, with no gap before the timer: only one run may own the switch.
          starts = !isHoldingFlow
          if (starts) isHoldingFlow = true
        }
      }
    } catch (error) {
      logError($, 'prompt.submit before', error)
    }

    // Only a submission that goes on to be stored is worth matching by its text:
    // a held prompt is dropped, never reaches `session.append`, and its row is
    // then matched by some later prompt that happens to say the same words.
    if ((isPersonOrigin(e.origin) || isOurUser(e.origin)) && !holds) {
      personTexts.push(e.text.trim())
      if (personTexts.length > 20) personTexts.shift()
    }
    if (!holds) return next(e)

    // A compaction cannot be asked for from inside this hook: a timer asks once
    // it returned, then the held prompt is submitted again as the person's own.
    if (!starts && heldSession !== undefined) {
      return { drop: 'ctx-mod：正在换窗口，这条消息排在后面，换完后按顺序处理' }
    }
    if (heldSession === undefined) return next(e)
    const session = heldSession
    try {
      $.clock.after(300, () => {
        void (async () => {
          try {
            // Only a message held for the expired cache calls for a switch: one that queued behind a switch which has since ended just goes in.
            if (isExpired) {
              switchReason = 'cold'
              try {
                await $.command.run({ command: 'compact' })
              } catch (error) {
                logError($, 'prompt.submit timer', error)
              } finally {
                switchReason = null
              }
            }
            await deliverHeld($, session)
          } catch (error) {
            logError($, 'prompt.submit deliver', error)
          } finally {
            isHoldingFlow = false
          }
        })()
      })
    } catch (error) {
      // No timer will ever deliver it: take the message back off the shelf and let it in.
      logError($, 'prompt.submit timer', error)
      isHoldingFlow = false
      await session.release(heldIdOf).catch(() => undefined)

      return next(e)
    }

    return {
      drop: isExpired
        ? 'ctx-mod：缓存已过期，先换窗口再处理这条消息'
        : 'ctx-mod：正在换窗口，这条消息排在后面，换完后按顺序处理',
    }
  })

  on('session.measure', async ($, e, next) => {
    if (!enabled) return next(e)
    try {
      const session = await sessionOf($)
      const id = await idOf($)
      if (session !== undefined && id !== undefined) {
        const limit = await limitFor($, id)
        if (limit !== undefined) {
          $.ui.status(describeFill(e.context.tokens, limit, session.window()))
        }
      }
    } catch (error) {
      logError($, 'session.measure', error)
    }

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    try {
      const session = sessions.get(e.sessionId)
      if (session !== undefined) {
        try {
          await session.flush()
        } catch {
          // A last write that fails is dropped; the session is going anyway.
        }
        sessions.delete(e.sessionId)
        limits.delete(e.sessionId)
      }
    } catch (error) {
      logError($, 'session.end', error)
    }
    // Nothing a finished session left behind may shape the next one: the wiring
    // is module-wide, and a new session id is all that separates them.
    switchReason = null
    committed = false
    isHoldingFlow = false
    awaitingPrefix = false
    lastStep = null
    continueAfterTurn = false
    personTexts.length = 0
    lastBackground.clear()
    calls.clear()

    return next(e)
  })
}

files.hooks/lib/history.ts:
// Pure history-plane logic: shard naming and packing, UTF-8 sizing without
// TextEncoder, clipping, search, paging and the whole-file write queue. Nothing
// here touches the engine, fs or a clock, so the callers inject the writer and
// this module stays testable in a bare interpreter.

import { OWN_TOOL_PREFIX, parseJsonl } from './types.ts'
import type { HistoryRecord, Overflow, Role } from './types.ts'

/** Shards rotate well before the engine's 4 MiB read ceiling, so a whole file still reads. */
export const MAX_SHARD_BYTES = 2 * 1024 * 1024

/** One record past this is clipped, so a single row can never fill a shard by itself. */
export const MAX_RECORD_CHARS = 200_000

/** A tool call's arguments past this are clipped in the row; the rest goes to the overflow files. */
export const MAX_ARGS_CHARS = 50_000

/**
 * One overflow file holds at most this many characters: UTF-8 makes that about
 * 3 MB at worst, which stays under the engine's 4 MiB read ceiling.
 */
export const OVERFLOW_PART_CHARS = 1_000_000

/** Three digits keep shard names sorting in window order for windows up to 999. */
const windowTag = (window: number): string => `w${String(window).padStart(3, '0')}`

/**
 * Part 0 is the plain name. Parts 1..25 take the letters b..z, which keeps a
 * rotation short; later parts fall back to digits, which never run out.
 */
const partTag = (part: number): string => {
  if (part <= 0) return ''
  if (part <= 25) return `-${String.fromCharCode(97 + part)}`

  return `-p${part}`
}

/** The file a window's shard part lives in; the caller writes the whole file at once. */
export const shardName = (window: number, part: number): string =>
  `history-${windowTag(window)}${partTag(part)}.jsonl`

/** The file a segment starts in: its name carries the seq of the segment's first row. */
export const segmentName = (window: number, seq: number): string =>
  `history-${windowTag(window)}.s${String(seq).padStart(6, '0')}.jsonl`

/**
 * The seq a segment file's name carries, or null when the name is not a segment
 * of this window. A seq may outgrow six digits; it is still read back exactly.
 */
export const segmentSeq = (name: string, window: number): number | null => {
  const head = `history-${windowTag(window)}.s`
  if (!name.startsWith(head) || !name.endsWith('.jsonl')) return null
  const digits = name.slice(head.length, -'.jsonl'.length)
  if (!/^\d+$/.test(digits)) return null
  const seq = Number(digits)

  return Number.isSafeInteger(seq) && seq > 0 ? seq : null
}

/** The small file naming a window's segment range, written at checkpoints and window switches. */
export const manifestName = (window: number): string => `history-${windowTag(window)}.manifest.json`

export type WindowManifest = {
  version: 1 | 2
  window: number
  firstSeq: number
  lastSeq: number
  count: number
  /** Version 2: the first seq of every segment file. Version 1 held one record per segment. */
  segments?: number[]
}

/** A manifest read back from disk, or null when it is damaged, foreign or impossible. */
export const parseManifest = (text: string, window: number): WindowManifest | null => {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return null
  }
  if (typeof raw !== 'object' || raw === null) return null
  const one = raw as Partial<WindowManifest>
  if ((one.version !== 1 && one.version !== 2) || one.window !== window) return null
  if (!Number.isInteger(one.firstSeq) || !Number.isInteger(one.lastSeq) || !Number.isInteger(one.count)) return null
  if (one.firstSeq === undefined || one.lastSeq === undefined || one.count === undefined) return null
  if (one.firstSeq < 1 || one.lastSeq < one.firstSeq || one.count < 0) return null
  if (one.version === 2) {
    // A v2 manifest names its segment starts; one that does not is treated as a
    // v1 range, whose every seq was a start, so older data still opens.
    const segments = Array.isArray(one.segments)
      ? one.segments.filter(
          (seq): seq is number => typeof seq === 'number' && Number.isSafeInteger(seq) && seq > 0,
        )
      : []
    if (segments.length > 0) return { version: 2, window, firstSeq: one.firstSeq, lastSeq: one.lastSeq, count: one.count, segments }
  }

  return { version: 1, window, firstSeq: one.firstSeq, lastSeq: one.lastSeq, count: one.count }
}

/**
 * The rows a history file holds, keeping every complete line and dropping an
 * unfinished tail. A write cut off mid-line leaves no newline behind, and half
 * a row must never be read as one; a complete but unparsable line is skipped as
 * `parseJsonl` always does.
 */
export const parseHistoryText = (text: string): HistoryRecord[] => {
  const end = text.lastIndexOf('\n')
  if (end < 0) return []

  return parseJsonl<HistoryRecord>(text.slice(0, end + 1))
}

/**
 * The UTF-8 length of a string, counted code point by code point: TextEncoder
 * and Buffer are both out of reach in the engine's module sandbox.
 */
export const byteLength = (text: string): number => {
  let bytes = 0
  for (const char of text) {
    const point = char.codePointAt(0) ?? 0
    if (point < 0x80) bytes += 1
    else if (point < 0x800) bytes += 2
    else if (point < 0x10000) bytes += 3
    else bytes += 4
  }

  return bytes
}

/** Whether a UTF-16 unit is the first half of a surrogate pair. */
const isHighSurrogate = (unit: number): boolean => unit >= 0xd800 && unit <= 0xdbff

/** The head of an over-long field plus one line saying how long the original was and where the rest lives. */
const clipField = (text: string, limit: number): string => {
  let head = text.slice(0, limit)
  // Never cut a surrogate pair in half: the lone half would be unencodable.
  if (isHighSurrogate(head.charCodeAt(head.length - 1))) head = head.slice(0, -1)

  return `${head}\n[已截断：原文 ${text.length} 字符，可分页读全文，搜索只查这一段]`
}

/**
 * Cuts a text into the overflow files' contents. A part ends one unit early
 * when its last unit would split a surrogate pair, so a part's start is not
 * always a multiple of the part size: `cuts` then lists where each later part
 * starts, and is left out while the plain arithmetic holds.
 */
export const splitParts = (text: string): { parts: string[]; cuts?: number[] } => {
  const parts: string[] = []
  const cuts: number[] = []
  let isShifted = false
  let start = 0
  while (start < text.length) {
    let end = Math.min(text.length, start + OVERFLOW_PART_CHARS)
    if (end < text.length && isHighSurrogate(text.charCodeAt(end - 1))) end -= 1
    parts.push(text.slice(start, end))
    if (end < text.length) {
      cuts.push(end)
      if (end !== parts.length * OVERFLOW_PART_CHARS) isShifted = true
    }
    start = end
  }

  return isShifted ? { parts, cuts } : { parts }
}

const overflowOf = (text: string): Overflow => {
  const { parts, cuts } = splitParts(text)

  return { chars: text.length, parts: parts.length, ...(cuts === undefined ? {} : { cuts }) }
}

/** Where an overflow file begins in the original text. */
const partStart = (overflow: Overflow, part: number): number =>
  part <= 0 ? 0 : overflow.cuts?.[part - 1] ?? part * OVERFLOW_PART_CHARS

/** The overflow file that holds one field of one row; `field` is `text` or `args`. */
export const overflowName = (seq: number, field: 'text' | 'args', part: number): string =>
  `big-${seq}-${field}-${part}.txt`

/** The parts that hold any of the characters from `start` up to `end`, in order. */
export const partsCovering = (overflow: Overflow, start: number, end: number): number[] => {
  const wanted: number[] = []
  for (let part = 0; part < overflow.parts; part += 1) {
    const from = partStart(overflow, part)
    const to = part + 1 < overflow.parts ? partStart(overflow, part + 1) : overflow.chars
    if (to > start && from < end) wanted.push(part)
  }

  return wanted
}

/** Where the first of the given parts begins; the caller joins the parts it read and slices from here. */
export const partOrigin = (overflow: Overflow, part: number): number => partStart(overflow, part)

/**
 * The record as it is kept in a shard: a text or arguments field past its limit
 * keeps only its head plus one line saying how long the original was, and the
 * row notes how many overflow files the whole original goes into. Everything a
 * consumer reads from the row stays as short as it ever was.
 */
export const clipRecord = (record: HistoryRecord): HistoryRecord => {
  const clipped: HistoryRecord = { ...record }
  const overflow: NonNullable<HistoryRecord['overflow']> = {}
  if (record.text.length > MAX_RECORD_CHARS) {
    clipped.text = clipField(record.text, MAX_RECORD_CHARS)
    overflow.text = overflowOf(record.text)
  }
  if (record.args !== undefined && record.args.length > MAX_ARGS_CHARS) {
    clipped.args = clipField(record.args, MAX_ARGS_CHARS)
    overflow.args = overflowOf(record.args)
  }
  if (overflow.text !== undefined || overflow.args !== undefined) clipped.overflow = overflow

  return clipped
}

/**
 * A tool call's arguments as plain text: one `key: value` segment per top-level
 * key, strings as they are (they may span lines), anything else as JSON. The
 * live path and the import path both write it, so a row reads the same either way.
 */
export const formatArgs = (args: Readonly<Record<string, unknown>>): string => {
  const segments: string[] = []
  for (const [key, value] of Object.entries(args)) {
    let shown: string | undefined
    if (typeof value === 'string') {
      shown = value
    } else {
      try {
        shown = JSON.stringify(value)
      } catch {
        // A value JSON cannot hold (a cycle, a BigInt) is still worth its name.
        shown = String(value)
      }
    }
    if (shown !== undefined) segments.push(`${key}: ${shown}`)
  }

  return segments.join('\n')
}

/**
 * One line naming the blocks of a row that are not text, so an image or a
 * document does not vanish from the history without a trace; empty when every
 * block is text. A part that carries its own text is counted as text, as the
 * extraction of the text does; `skip` leaves out types the row already names.
 */
export const nonTextNote = (blocks: readonly unknown[], skip: readonly string[] = []): string => {
  const counts = new Map<string, number>()
  for (const block of blocks) {
    const part = typeof block === 'object' && block !== null ? (block as { type?: unknown; text?: unknown }) : {}
    if (typeof (part as { text?: unknown }).text === 'string') continue
    const type = typeof part.type === 'string' ? part.type : 'unknown'
    if (type === 'text' || skip.includes(type)) continue
    counts.set(type, (counts.get(type) ?? 0) + 1)
  }
  if (counts.size === 0) return ''

  return `[非文本内容：${[...counts].map(([type, count]) => `${type}×${count}`).join('、')}]`
}

/** One shard file: its window, its rotation index, its rows and their running byte cost. */
export type Shard = { window: number; part: number; rows: HistoryRecord[]; bytes: number }

export const emptyShard = (window: number, part = 0): Shard => ({ window, part, rows: [], bytes: 0 })

/** What one row costs in a shard: its JSON, plus the newline that joins the lines. */
const recordBytes = (record: HistoryRecord): number => byteLength(JSON.stringify(record)) + 1

/**
 * Places one record into a shard, returning the shard to keep and whether a new
 * file was opened. A record from another window starts that window's part 0, and
 * one that would push a non-empty shard past the ceiling rotates within the same
 * window; a record too big for any shard still lands alone in an empty one.
 *
 * Appending into the current shard pushes onto that shard's own `rows` and hands
 * back the same array, which keeps a run of records linear rather than quadratic
 * in the array length. The shard passed in is therefore consumed: work with the
 * returned shard from then on, and never read the old one again. A rotation or a
 * window change still builds a fresh shard and leaves the old one whole, since
 * the caller has already written and stored it under its own name.
 */
export const appendRecord = (
  shard: Shard,
  record: HistoryRecord,
): { shard: Shard; isNew: boolean } => {
  const bytes = recordBytes(record)

  if (record.window !== shard.window) {
    return { shard: { ...emptyShard(record.window, 0), rows: [record], bytes }, isNew: true }
  }

  if (shard.rows.length > 0 && shard.bytes + bytes > MAX_SHARD_BYTES) {
    return { shard: { ...emptyShard(shard.window, shard.part + 1), rows: [record], bytes }, isNew: true }
  }

  shard.rows.push(record)
  shard.bytes += bytes

  return { shard, isNew: false }
}

export type SearchQuery = {
  query: string
  window?: number
  role?: Role
  tool?: string
  path?: string
  /** Only rows that came in by this door; it also lifts the default skip of the background rows. */
  door?: string
  limit?: number
}

export type SearchHit = {
  seq: number
  window: number
  role: Role
  tool?: string
  path?: string
  door?: string
  name?: string
  /** The tool call's input summary, when the row has one. */
  input?: string
  excerpt: string
  /**
   * Set when the match was only in a clipped field's overflow file: the field it is in
   * and its absolute character offset in the original, for a `history read` to start at.
   */
  overflow?: { field: 'text' | 'args'; offset: number }
}

const EXCERPT_PAD = 80
const EXCERPT_HEAD = 160
const SEARCH_LIMIT_DEFAULT = 20
const SEARCH_LIMIT_MAX = 100

/**
 * The cap the caller asked for, or the default. A value that is not a finite
 * positive number — NaN, a string, Infinity, zero, a negative — must never be
 * read as "no cap" and hand back the whole history, which is exactly what a
 * comparison against NaN does.
 */
const searchLimit = (limit: unknown): number => {
  if (typeof limit !== 'number' || !Number.isFinite(limit) || limit < 1) return SEARCH_LIMIT_DEFAULT

  return Math.min(Math.floor(limit), SEARCH_LIMIT_MAX)
}

/** A window filter means a finite number; anything else is no filter at all. */
const windowFilter = (window: unknown): number | undefined =>
  typeof window === 'number' && Number.isFinite(window) ? window : undefined

/** Only the three role names filter; anything else is ignored, never turned into an empty answer. */
const roleFilter = (role: unknown): Role | undefined =>
  role === 'user' || role === 'assistant' || role === 'tool' ? role : undefined

/** A text filter is a string or nothing; a non-string must not throw. */
const textFilter = (value: unknown): string | undefined => (typeof value === 'string' ? value : undefined)

/** Whether a row is one of this mod's own tool calls; those stay on disk but are not the work. */
export const isOwnRow = (row: HistoryRecord): boolean =>
  typeof row.tool === 'string' && row.tool.startsWith(OWN_TOOL_PREFIX)

/**
 * Whether a row is the engine's own background (an attachment, a hook's context,
 * a note) rather than something said or done. A person's message that arrived
 * as a `queued_command` attachment is the exception: it is the work.
 */
export const isBackgroundRow = (row: Pick<HistoryRecord, 'door' | 'name'>): boolean =>
  row.door === 'hook-context' ||
  row.door === 'note' ||
  (row.door === 'attachment' && row.name !== 'queued_command')

/** A path is written with either separator; folding them makes one filter work for both. */
const flattenPath = (path: string): string => path.replace(/\\/g, '/').toLowerCase()

/** Newlines inside a one-line excerpt would break the table the caller prints. */
const oneLine = (text: string): string => text.replace(/[\r\n]/g, ' ')

/** The window around the first match, the match itself included. */
const excerptAround = (text: string, at: number, width: number): string =>
  oneLine(text.slice(Math.max(0, at - EXCERPT_PAD), Math.min(text.length, at + width + EXCERPT_PAD)))

/**
 * Literal, case-insensitive search over the records, newest first. An empty
 * query skips text matching and only applies the filters, so it doubles as
 * "what happened in this window". Every field is read defensively: the callers
 * cast a model's tool input straight to `SearchQuery`, so a missing or wrongly
 * typed field means "no filter", never a throw and never a widened answer.
 * This mod's own tool rows are skipped unless the caller names a tool filter:
 * a search is about the work, and a tool filter is how they are still found.
 * The engine's background rows are skipped the same way unless a door is named.
 */
/** Reads one part of a field whose original was set aside; null when it cannot be had. */
export type OverflowReader = (seq: number, field: 'text' | 'args', part: number) => Promise<string | null>

/**
 * One overflow part that could not be searched: the reader said it was absent,
 * threw, or handed back a length that does not match the row's own metadata.
 * A search skips that file, says so through `SearchOptions.onOverflowError`,
 * and still searches the row's other parts and every other row.
 */
export type OverflowFailure = {
  seq: number
  field: 'text' | 'args'
  part: number
  reason: 'missing' | 'unreadable' | 'truncated'
  /** For `truncated`: the characters the metadata promised and what the file held. */
  expected?: number
  actual?: number
}

/** What an asynchronous search reports besides its hits. */
export type SearchOptions = {
  /** Told once per part a search had to skip; a throwing reporter never breaks the search. */
  onOverflowError?: (failure: OverflowFailure) => void
}

/** A match that only survived in the overflow files: the field and its absolute offset in the original. */
type OverflowMatch = { field: 'text' | 'args'; offset: number; excerpt: string }

/** How many characters one part of a field holds, from the row's own metadata. */
const partSpan = (overflow: Overflow, part: number): number =>
  (part + 1 < overflow.parts ? partStart(overflow, part + 1) : overflow.chars) - partStart(overflow, part)

/**
 * The first occurrence of `needle` in a field's overflow files. Parts are read one at a
 * time, and a match that straddles a part boundary is still found: the last few
 * characters of the previous part are kept in front of the next one, and the offset
 * is measured against the original field, not the part.
 */
const overflowMatch = async (
  row: HistoryRecord,
  needle: string,
  readOverflow: OverflowReader,
  onFailure?: (failure: OverflowFailure) => void,
): Promise<OverflowMatch | null> => {
  const report = (failure: OverflowFailure): void => {
    try {
      onFailure?.(failure)
    } catch {
      // A reporter must never change what a search finds.
    }
  }
  const overlap = needle.length - 1
  for (const field of ['text', 'args'] as const) {
    const overflow = row.overflow?.[field]
    if (overflow === undefined) continue
    let tail = ''
    for (let part = 0; part < overflow.parts; part += 1) {
      const span = partSpan(overflow, part)
      let text: string | null
      try {
        text = await readOverflow(row.seq, field, part)
      } catch {
        // One unreadable file must not fail the whole search: skip it and say so.
        report({ seq: row.seq, field, part, reason: 'unreadable' })
        // The next part does not continue this one, so a match across the gap would be a lie.
        tail = ''
        continue
      }
      if (text === null) {
        report({ seq: row.seq, field, part, reason: 'missing' })
        tail = ''
        continue
      }
      // A part whose length is not what the row promised would shift every offset after it.
      if (text.length !== span) {
        report({ seq: row.seq, field, part, reason: 'truncated', expected: span, actual: text.length })
        tail = ''
        continue
      }
      const probe = tail + text
      const at = probe.toLowerCase().indexOf(needle)
      if (at >= 0) {
        return {
          field,
          offset: partOrigin(overflow, part) - tail.length + at,
          excerpt: excerptAround(probe, at, needle.length),
        }
      }
      tail = overlap <= 0 ? '' : text.slice(-overlap)
    }
  }

  return null
}

/**
 * Literal, case-insensitive search over the records, newest first. An empty
 * query skips text matching and only applies the filters, so it doubles as
 * "what happened in this window". Every field is read defensively: the callers
 * cast a model's tool input straight to `SearchQuery`, so a missing or wrongly
 * typed field means "no filter", never a throw and never a widened answer.
 * This mod's own tool rows are skipped unless the caller names a tool filter:
 * a search is about the work, and a tool filter is how they are still found.
 * The engine's background rows are skipped the same way unless a door is named.
 *
 * Without `readOverflow` the function is pure and synchronous. Given a reader,
 * it returns a promise and also looks inside a clipped field's overflow files,
 * but only for a row whose inline fields did not match, so an ordinary search
 * never pays for them. Such a hit carries the absolute offset in the original.
 */
export function search(rows: readonly HistoryRecord[], query: SearchQuery): SearchHit[]
export function search(
  rows: readonly HistoryRecord[],
  query: SearchQuery,
  readOverflow: OverflowReader,
  options?: SearchOptions,
): Promise<SearchHit[]>
export function search(
  rows: readonly HistoryRecord[],
  query: SearchQuery,
  readOverflow?: OverflowReader,
  options?: SearchOptions,
): SearchHit[] | Promise<SearchHit[]> {
  const limit = searchLimit(query.limit)
  const window = windowFilter(query.window)
  const role = roleFilter(query.role)
  const tool = textFilter(query.tool)
  const door = textFilter(query.door)
  const skipOwn = tool === undefined
  const filterPath = textFilter(query.path)
  const needle = (typeof query.query === 'string' ? query.query : '').toLowerCase()
  const pathNeedle = filterPath === undefined ? undefined : flattenPath(filterPath)
  const ordered = [...rows].sort((a, b) => b.seq - a.seq)

  const wanted = (row: HistoryRecord): boolean => {
    if (window !== undefined && row.window !== window) return false
    if (role !== undefined && row.role !== role) return false
    if (tool !== undefined && row.tool !== tool) return false
    if (skipOwn && isOwnRow(row)) return false
    if (door !== undefined ? row.door !== door : isBackgroundRow(row)) return false
    if (pathNeedle !== undefined) {
      if (row.path === undefined || !flattenPath(row.path).includes(pathNeedle)) return false
    }

    return true
  }

  /** The excerpt when the row's own fields match, or null when only its overflow might. */
  const inlineExcerpt = (row: HistoryRecord): string | null => {
    if (needle === '') return oneLine(row.text.slice(0, EXCERPT_HEAD))
    const at = row.text.toLowerCase().indexOf(needle)
    // A word that only survived in the call's arguments, or in their summary, still
    // matches: the point of those fields is to find a past call by what it was asked.
    const inArgs = at < 0 ? (row.args ?? '').toLowerCase().indexOf(needle) : -1
    const inInput = at < 0 && inArgs < 0 ? (row.input ?? '').toLowerCase().indexOf(needle) : -1
    if (at < 0 && inArgs < 0 && inInput < 0) return null

    return at >= 0
      ? excerptAround(row.text, at, needle.length)
      : inArgs >= 0
        ? excerptAround(row.args ?? '', inArgs, needle.length)
        : excerptAround(row.input ?? '', inInput, needle.length)
  }

  const hitOf = (row: HistoryRecord, excerpt: string, overflow?: OverflowMatch): SearchHit => {
    const hit: SearchHit = { seq: row.seq, window: row.window, role: row.role, excerpt }
    if (row.tool !== undefined) hit.tool = row.tool
    if (row.path !== undefined) hit.path = row.path
    if (row.input !== undefined) hit.input = row.input
    if (row.door !== undefined) hit.door = row.door
    if (row.name !== undefined) hit.name = row.name
    if (overflow !== undefined) hit.overflow = { field: overflow.field, offset: overflow.offset }

    return hit
  }

  if (readOverflow === undefined) {
    const hits: SearchHit[] = []
    for (const row of ordered) {
      if (hits.length >= limit) break
      if (!wanted(row)) continue
      const excerpt = inlineExcerpt(row)
      if (excerpt !== null) hits.push(hitOf(row, excerpt))
    }

    return hits
  }

  return (async (): Promise<SearchHit[]> => {
    const hits: SearchHit[] = []
    for (const row of ordered) {
      if (hits.length >= limit) break
      if (!wanted(row)) continue
      const excerpt = inlineExcerpt(row)
      if (excerpt !== null) {
        hits.push(hitOf(row, excerpt))
        continue
      }
      const found = await overflowMatch(row, needle, readOverflow, options?.onOverflowError)
      if (found !== null) hits.push(hitOf(row, found.excerpt, found))
    }

    return hits
  })()
}

export type ReadResult =
  | { found: false }
  | {
      found: true
      seq: number
      window: number
      role: Role
      tool?: string
      path?: string
      ts: number
      /** Which field the slice is of: the result's text, or the call's arguments. */
      field: ReadField
      text: string
      total: number
      hasMore: boolean
      /** Said before the text when the field is not what the caller asked for in full. */
      note?: string
      /** Set when the field was cut at the row: the whole original is in the overflow files. */
      overflow?: Overflow
    }

type FoundResult = Extract<ReadResult, { found: true }>

/** What `history` read can page through: a row's text, or the arguments of the call behind it. */
export type ReadField = 'text' | 'input'

const READ_LENGTH_DEFAULT = 4_000
const READ_LENGTH_MAX = 20_000

/** A count that must be a finite number to be usable, floor included; otherwise the fallback. */
const countOr = (value: unknown, fallback: number): number =>
  typeof value === 'number' && Number.isFinite(value) ? Math.floor(value) : fallback

/** The slice a read of `total` characters covers, with the same defaults and caps for every field. */
export const sliceBounds = (total: number, offset: unknown, length: unknown): { start: number; end: number } => {
  const start = Math.max(0, countOr(offset, 0))
  const asked = countOr(length, READ_LENGTH_DEFAULT)

  return { start, end: Math.min(total, start + Math.max(0, Math.min(asked, READ_LENGTH_MAX))) }
}

/**
 * Reads one record's text in slices, so a clipped-in-shard row can be paged
 * back in full without pulling megabytes through a single tool result. The
 * seq, offset and length come from a cast tool input, so a value that is not a
 * finite number reads as "not found", "from the start" and "the default slice"
 * rather than as a NaN that would silently slice nothing. What a row keeps
 * inline is all this reads: when it names an `overflow`, the caller reads the
 * files behind it and slices there.
 */
export const readRecord = (
  rows: readonly HistoryRecord[],
  seq: number,
  offset = 0,
  length = READ_LENGTH_DEFAULT,
  field: ReadField = 'text',
): ReadResult => {
  if (typeof seq !== 'number' || !Number.isFinite(seq)) return { found: false }
  const row = rows.find(candidate => candidate.seq === seq)
  if (row === undefined) return { found: false }

  const isInput = field === 'input'
  // A row from before the arguments were kept has only the summary, and says so.
  const body = isInput ? row.args ?? row.input ?? '' : row.text
  const { start, end } = sliceBounds(body.length, offset, length)

  const result: FoundResult = {
    found: true,
    seq: row.seq,
    window: row.window,
    role: row.role,
    ts: row.ts,
    field,
    text: body.slice(start, end),
    total: body.length,
    hasMore: end < body.length,
  }
  if (row.tool !== undefined) result.tool = row.tool
  if (row.path !== undefined) result.path = row.path
  if (isInput && row.args === undefined) {
    result.note =
      row.input === undefined ? '这一行没有记录调用参数。' : '这是旧记录，只留了参数摘要，没有参数全文。'
  }
  const overflow = isInput ? row.overflow?.args : row.overflow?.text
  if (overflow !== undefined) result.overflow = overflow

  return result
}

export type Action = { seq: number; tool: string; path?: string; input?: string; isError: boolean; head: string }

const HEAD_CHARS = 80

/** The head kept for a call made in the step that asked for the switch: its summary is the only result the new window sees. */
const SWITCH_HEAD_CHARS = 800

/**
 * The tail of one window's tool calls, oldest first, as a short recap of what was
 * done. This mod's own calls are dropped before the tail is taken, so the count
 * is spent on the work rather than on the ledger and history calls that record it.
 */
export const recentActions = (
  rows: readonly HistoryRecord[],
  window: number,
  count: number,
  /** The history seq at the switch's approval: calls after it keep a longer head. */
  longFrom?: number,
): Action[] => {
  if (count <= 0) return []

  const picked = [...rows]
    .filter(row => row.window === window && row.role === 'tool' && !isOwnRow(row))
    .sort((a, b) => a.seq - b.seq)
    .slice(-count)

  return picked.map(row => {
    const action: Action = {
      seq: row.seq,
      tool: row.tool ?? '',
      isError: row.isError === true,
      head: oneLine(row.text.slice(0, longFrom !== undefined && row.seq > longFrom ? SWITCH_HEAD_CHARS : HEAD_CHARS)),
    }
    if (row.path !== undefined) action.path = row.path
    if (row.input !== undefined) action.input = row.input

    return action
  })
}

/** One deferred tool a window loaded and used: an MCP server's tools share one line. */
export type LoadedTool = { name: string; calls: number }

const MAX_LOADED_TOOLS = 8
const MCP_PREFIX = 'mcp__'
const SELECT_PREFIX = 'select:'

/**
 * The group a tool is listed under: an MCP tool under its server (`mcp__<server>__*`),
 * any other name stands alone. Exported so the cache measure and the handoff name a
 * load by the same group.
 */
export const toolGroupOf = (name: string): string => {
  if (!name.startsWith(MCP_PREFIX)) return name
  const rest = name.slice(MCP_PREFIX.length)
  const cut = rest.indexOf('__')

  return cut <= 0 || cut + 2 >= rest.length ? name : `${MCP_PREFIX}${rest.slice(0, cut)}__*`
}

/**
 * The groups a ToolSearch query would load, out of the `known` ones, in `known`'s order. A
 * `select:` query names its tools. Any other query is a keyword, matched against each group's
 * core name (the server of an MCP group, the name of any other); the dashes and underscores
 * of both sides are read as spaces in a second try, so `computer use` finds `computer-use`.
 */
export const groupsWanted = (query: string, known: readonly string[]): string[] => {
  const groups = [...new Set(known)]
  const text = query.trim()
  if (text.startsWith(SELECT_PREFIX)) {
    const named = new Set(
      text
        .slice(SELECT_PREFIX.length)
        .split(',')
        .map(part => part.trim())
        .filter(part => part !== '')
        .map(toolGroupOf),
    )

    return groups.filter(group => named.has(group))
  }

  const needle = text.toLowerCase()
  const spaced = needle.replace(/[-_]/g, ' ')

  return groups.filter(group => {
    const core = (group.startsWith(MCP_PREFIX) && group.endsWith('__*') ? group.slice(MCP_PREFIX.length, -3) : group).toLowerCase()

    return needle.includes(core) || spaced.includes(core.replace(/[-_]/g, ' '))
  })
}

/**
 * The names one ToolSearch row loaded. Rows written before `loaded` existed only
 * kept the query, so for those the `select:` names are read back out of it.
 */
const loadedOf = (row: HistoryRecord): string[] => {
  if (Array.isArray(row.loaded)) return row.loaded.filter(name => typeof name === 'string')
  const query = row.input ?? ''
  if (!query.startsWith(SELECT_PREFIX)) return []

  return query
    .slice(SELECT_PREFIX.length)
    .split(',')
    .map(part => part.trim())
    .filter(part => part !== '')
}

/**
 * The deferred tools one window loaded and then actually called, most useful
 * first by when they were loaded. A tool loaded and never used is left out, and
 * an MCP server's tools are summed into one line so a big toolkit stays short.
 */
export const loadedTools = (rows: readonly HistoryRecord[], window: number): LoadedTool[] => {
  const inWindow = [...rows]
    .filter(row => row.window === window && row.role === 'tool')
    .sort((a, b) => a.seq - b.seq)

  const calls = new Map<string, number>()
  for (const row of inWindow) {
    const name = row.tool ?? ''
    calls.set(name, (calls.get(name) ?? 0) + 1)
  }

  const loaded = new Set<string>()
  for (const row of inWindow) {
    if (row.tool !== 'ToolSearch') continue
    for (const name of loadedOf(row)) loaded.add(name)
  }

  const tools = new Map<string, number>()
  for (const name of loaded) {
    const used = calls.get(name) ?? 0
    if (used === 0) continue
    const key = toolGroupOf(name)
    tools.set(key, (tools.get(key) ?? 0) + used)
  }

  return [...tools]
    .slice(0, MAX_LOADED_TOOLS)
    .map(([name, count]) => ({ name, calls: count }))
}

/**
 * The person's own last prompts, across windows: what to carry into a new window.
 * Only rows marked as a person's count, so the engine's deliveries, notices and
 * attachments never become a request; a message typed mid-turn is marked when
 * the hook recognises it.
 */
export const personRequests = (rows: readonly HistoryRecord[], count: number): HistoryRecord[] => {
  if (count <= 0) return []

  return [...rows]
    .filter(row => row.isPerson === true)
    .sort((a, b) => a.seq - b.seq)
    .slice(-count)
}

/**
 * The model's reply each request came after, by the request's seq: a "可以" says
 * nothing without the question it answers. `rows` are in seq order.
 *
 * Only a reply made since the person last spoke counts: a second message in a row,
 * or one typed mid-turn before the model said anything, answers no new reply, and
 * pointing it at the previous turn's would mislead. Such a request is left out.
 */
export const repliesAnswered = (
  rows: readonly HistoryRecord[],
  requests: readonly HistoryRecord[],
): Map<number, HistoryRecord> => {
  const answered = new Map<number, HistoryRecord>()
  for (const request of requests) {
    let reply: HistoryRecord | undefined
    for (const row of rows) {
      if (row.seq >= request.seq) break
      if (row.isPerson === true) reply = undefined
      // A row with a door is the engine's delivery or note, never the model's own reply.
      else if (row.role === 'assistant' && row.door === undefined && row.text.trim() !== '') reply = row
    }
    if (reply !== undefined) answered.set(request.seq, reply)
  }

  return answered
}

/** What the queue tells its owner: a write that landed, and a push folded into one not yet started. */
export type QueueHooks = {
  /** Called after a write succeeds, with its UTF-8 size. */
  onWrite?: (path: string, bytes: number) => void
  /** Called when a push is merged into a same-path push that has not started yet. */
  onCoalesce?: (path: string) => void
}

/** One whole-file write waiting its turn. */
type Job = {
  path: string
  text: string
  done: Promise<boolean>
  finish: (ok: boolean) => void
}

export type Queue = {
  /**
   * Queues one whole-file write, merging into a same-path write that has not started.
   * Resolves to whether the write that finally ran succeeded, so a caller can tell a
   * file on disk from one that only exists in memory; it never rejects.
   */
  push: (path: string, text: string) => Promise<boolean>
  /** Resolves once every write queued so far has finished. */
  idle: () => Promise<void>
}

/**
 * Serializes whole-file writes, since the engine can only overwrite a file
 * whole: one write runs at a time, a not-yet-started write to the same path is
 * replaced by the newer text, and a failing write is reported but never stalls
 * the queue or rejects the caller's promise.
 */
export const createQueue = (
  write: (path: string, text: string) => Promise<void>,
  onError?: (path: string, error: unknown) => void,
  hooks?: QueueHooks,
): Queue => {
  const pending: Job[] = []
  const idlers: (() => void)[] = []
  let isRunning = false

  const settleIdle = (): void => {
    if (isRunning || pending.length > 0) return
    while (idlers.length > 0) idlers.pop()?.()
  }

  /**
   * Reports a failed write without letting the reporter break the queue: a
   * throwing `onError` would otherwise escape the run loop and leave every
   * queued push, and its promise, waiting forever.
   */
  const report = (path: string, error: unknown): void => {
    try {
      onError?.(path, error)
    } catch {
      // The reporter's own failure is the caller's to notice, not the queue's to stall on.
    }
  }

  const run = async (): Promise<void> => {
    if (isRunning) return
    isRunning = true
    try {
      for (;;) {
        const job = pending.shift()
        if (job === undefined) break
        let ok = false
        try {
          await write(job.path, job.text)
          ok = true
        } catch (error) {
          report(job.path, error)
        } finally {
          if (ok) {
            try {
              hooks?.onWrite?.(job.path, byteLength(job.text))
            } catch {
              // A counter must never change what the queue reports.
            }
          }
          // Settled on either path, so no push is ever left hanging.
          job.finish(ok)
        }
      }
    } finally {
      isRunning = false
      settleIdle()
    }
  }

  const push = (path: string, text: string): Promise<boolean> => {
    const open = pending.find(job => job.path === path)
    if (open !== undefined) {
      open.text = text
      try {
        hooks?.onCoalesce?.(path)
      } catch {
        // A counter must never change what the queue reports.
      }
      return open.done
    }

    let settle = (_ok: boolean): void => {}
    const done = new Promise<boolean>(resolve => {
      settle = resolve
    })
    const job: Job = { path, text, done, finish: ok => settle(ok) }
    pending.push(job)
    // The loop already contains its own failures; the catch is the last guard
    // that a drain can never surface as an unhandled rejection.
    void run().catch(() => {})

    return job.done
  }

  const idle = (): Promise<void> =>
    new Promise<void>(resolve => {
      if (!isRunning && pending.length === 0) {
        resolve()
        return
      }
      idlers.push(resolve)
    })

  return { push, idle }
}

files.hooks/lib/session.ts:
// One session's state: it owns the files under `dir`, wires the pure library
// modules together and is the only thing the engine hooks talk to. Nothing here
// reaches the engine, the clock or the disk on its own — every file and every
// timestamp arrives through the injected `Io`, so the module runs in a bare
// interpreter with no fs, no DOM and no timers.

import type {
  Anchor,
  CacheState,
  Config,
  FileActivity,
  HistoryRecord,
  LedgerEntry,
  LedgerInput,
  Overflow,
  Role,
  TaskStatus,
} from './types.ts'
import { estimateTokens, isRelay, parseJsonl, toJsonl } from './types.ts'
import {

  byteLength,

  clipRecord,
  createQueue,

  loadedTools,
  personRequests,
  repliesAnswered,
  readRecord,
  recentActions,
  search,
  groupsWanted,
  isOwnRow,
  manifestName,
  overflowName,
  parseHistoryText,
  parseManifest,
  partOrigin,
  partsCovering,
  segmentName,
  segmentSeq,
  shardName,
  sliceBounds,
  splitParts,
  toolGroupOf,
} from './history.ts'
import type { LoadedTool, OverflowFailure, SearchHit, Shard } from './history.ts'
import { archiveName, hasFreshEntry, pageOf, renderHome, stamp, tasksOf, turnPage, validate } from './ledger.ts'
import type { AnchorCheck, ArchivePage, TaskState } from './ledger.ts'
import { activityOf, filesOf, locate, pathKey, pathsToRead, relativePath, renderWorkset, snippetsOf } from './workset.ts'
import type { FileContent, OpenTask } from './workset.ts'
import { assemble, ENDED_STATE, renderAgents, renderCoverage, renderLoadReason, renderTools, rewriteOf } from './handoff.ts'
import type { RebuiltTool } from './handoff.ts'
import { describeFill, gateSwitch, isCold, judgeSwitch, levelOf } from './usage.ts'

export type Io = {
  read: (path: string) => Promise<string>
  write: (path: string, text: string) => Promise<void>
  now: () => number
  /** Told about every failed write, so the caller can log what the queue would otherwise swallow. */
  onWriteError?: (path: string, error: unknown) => void
  /** Whether the path exists; lets a failed read be told from an absent file. */
  exists?: (path: string) => Promise<boolean>
  /** Moves `from` over `to` in one step; without it a file is written in place. */
  rename?: (from: string, to: string) => Promise<void>
  /** Deletes the file; a missing file is not an error. */
  remove?: (path: string) => Promise<void>
  /** The names of the files in a directory; without it only the older shared table is read. */
  list?: (path: string) => Promise<readonly string[]>
  /**
   * The session's working directory. Only the handoff text uses it, to show paths inside it
   * relative to it; what is stored on disk keeps the absolute paths. Left out, paths stay as they are.
   */
  cwd?: () => string | undefined | Promise<string | undefined>
}

export type Env = {
  /** The context tokens the engine last reported; unknown on the first request. */
  tokens: number | undefined
  /** The compaction threshold the fill is measured against. */
  limit: number
  /** cache-keeper's published state, when that mod is loaded at all. */
  cache: CacheState | null
  fiveHourPercent: number | undefined
}

export type ToolResult = { result: string; isError?: true }

/** A switch the model asked for and the gate stood behind, until the turn ends. */
/** `requests` and `seq` are the request count and history seq at approval: calls of the approving step are let through. */
export type Pending = { reason: string; at: number; requests: number; seq: number }

/** One conversation row as the engine hands it over; seq, ts and window are ours. */
export type RecordInput = {
  uuid: string
  role: Role
  isPerson?: true
  /** The engine's origin kind of a prompt row, when the caller has it. */
  origin?: string
  tool?: string
  path?: string
  /** A one-line summary of the tool call's input, when the caller has one. */
  input?: string
  isError?: true
  /** The deferred tools a ToolSearch call loaded, when the caller has them. */
  loaded?: string[]
  /** The door of a row outside prompt, response and tool-result; those three carry none. */
  door?: string
  /** The attachment type behind such a row. */
  name?: string
  /** The tool call's arguments in full, as `formatArgs` writes them. */
  args?: string
  /** The `tool_use_id` of the call behind a tool row. */
  callId?: string
  text: string
}

/**
 * One subagent as the handoff needs it. The lib declares its own shape instead
 * of importing the engine's `AgentInfo`, so it stays loadable without the
 * `claude-code` types; the register maps the engine's rows onto this.
 */
export type AgentNote = {
  id: string
  type: string
  description: string
  state: string
  /** For an ended subagent: how long it has been idle and whether its cache is cold, ready to print. */
  cache?: string
}

/**
 * A subagent the main loop started, kept in the session: the engine lists an agent
 * only while it runs, but SendMessage still reaches it by `id` after it ends, so a
 * later window has to be told about it. `ended` is set when its own turn completes.
 */
export type AgentSeen = {
  id: string
  type: string
  description: string
  model?: string
  window: number
  ts: number
  ended?: boolean
  /** The Agent call's `name`, which SendMessage also takes as a recipient. */
  name?: string
  /** When the subagent last ran: its spawn, a resume, or the end of its latest turn. */
  lastActiveAt?: number
  /** Its latest request's input size (input + cache read + cache write), as the API reported it on `turn.step`. */
  contextTokens?: number
}

/**
 * A conversation row as the engine hands it over, kept to the fields this mod
 * files: the lib declares its own shape rather than importing the engine's, so
 * it stays loadable without the `claude-code` types.
 */
export type ImportedMessage = {
  role: 'user' | 'assistant'
  text: string
  toolUses: readonly {
    tool: string
    input?: unknown
    /** The tool call's input summary, computed by whoever built the message. */
    brief?: string
    /** The engine's id of the call, which later lines the conversation up with the rows. */
    callId?: string
    /** The call's arguments in full, as `formatArgs` writes them. */
    args?: string
    text?: string
    isError?: boolean
  }[]
}

/** How `openingOf` in handoff.ts begins; kept as a pattern so the window number may vary. */
const HANDOFF_OPENING = /^这是第\s*\d+\s*个窗口，上一个窗口的对话不在上下文里/

/** Whether a text is this mod's own handoff, the row a window opens with. */
export const isHandoffText = (text: string): boolean => HANDOFF_OPENING.test(text.trim())

/** Openings that are never a person's words, even from a confirmed source: a slash command is typed in the composer too. */
const ENVELOPE_OPENINGS = [
  '<command-name>',
  '<command-message>',
  '<command-args>',
  '<local-command-stdout>',
  '<local-command-stderr>',
  '<local-command-caveat>',
  '<task-notification>',
  '<system-reminder>',
] as const

/** A project thread's wake, up to the tag of the message that triggered it: that tag says who wrote it. */
const WAKE_TRIGGER = /<wake\b[^>]*>[\s\S]*?(<message\b[^>]*\btrigger="true"[^>]*>)/

/**
 * Whether a text is a wake some agent's message triggered, not a person's. A
 * wake arrives from the same origin whoever wrote the message, so only the
 * `from` on the triggering message tells the two apart.
 */
const isAgentWake = (text: string): boolean => {
  const trigger = WAKE_TRIGGER.exec(text)?.[1]

  return trigger !== undefined && !/\bfrom="human"/.test(trigger)
}

/**
 * Whether a user row came from a person. The engine files its own notices —
 * system reminders, command envelopes, task notifications, the continuation
 * header — in the same door, and the handoff must not read them as a request.
 * When the origin already says a person sent it, a text that merely starts with
 * `<` (a pasted `<task>` or HTML) is theirs; without an origin any `<` is doubted.
 */
export const looksLikePerson = (text: string, isConfirmed = false): boolean => {
  const head = text.trim()

  return !(
    (isConfirmed ? ENVELOPE_OPENINGS.some(opening => head.startsWith(opening)) : head.startsWith('<')) ||
    isAgentWake(head) ||
    head.startsWith('This session is being continued from a previous conversation') ||
    head.startsWith('Caveat:') ||
    head.startsWith('ctx-mod：') ||
    // The opening line of this mod's own handoff, which a window starts with as a user row.
    HANDOFF_OPENING.test(head)
  )
}

/**
 * The person rows as the home page shows them. Rows written before the
 * injected-head rule may still carry the engine's `<system-reminder>` block, and
 * the home page must show only what the person actually wrote.
 */
const displayRequests = (rows: readonly HistoryRecord[]): HistoryRecord[] =>
  rows.map(row => {
    const text = stripInjected(row.text)

    return text === row.text ? row : { ...row, text }
  })

/** How long an approved switch stays valid: past this the model's turn never ended. */
const PENDING_MS = 120_000

/** The cross-session table's file name; it sits beside the sessions' own directories. */
const COSTLY_FILE = 'costly.json'
/** The directory of the sessions' own cross-session files; each session writes only its own. */
const SHARED_DIR = 'costly'

/** The held-back user messages, kept in the session's directory until they are delivered. */
const HELD_FILE = 'held.json'

type HeldItem = { id: number; text: string; at: number }

/** Reads held.json; a missing or damaged file means nothing is held, never an error. */
const heldFrom = (text: string | null): HeldItem[] => {
  if (text === null) return []
  try {
    const parsed: unknown = JSON.parse(text)
    const items = typeof parsed === 'object' && parsed !== null ? (parsed as { items?: unknown }).items : undefined
    if (!Array.isArray(items)) return []
    const kept: HeldItem[] = []
    for (const item of items) {
      if (typeof item !== 'object' || item === null) continue
      const row = item as Record<string, unknown>
      if (typeof row.id !== 'number' || !Number.isInteger(row.id) || typeof row.text !== 'string') continue
      kept.push({ id: row.id, text: row.text, at: typeof row.at === 'number' ? row.at : 0 })
    }

    return kept.sort((a, b) => a.id - b.id)
  } catch {
    return []
  }
}

/**
 * How long a measure holds: past this the table forgets it, so a load is no longer held
 * back by it, and a rebuild that still happens is measured and recorded again.
 */
const SHARED_MS = 30 * 24 * 3_600_000

const REMINDER_OPEN = '<system-reminder>'
const REMINDER_CLOSE = '</system-reminder>'

/**
 * The text with the engine's injected notes stripped off its head. The engine
 * files a session-start hook's `<system-reminder>` block in the same door as a
 * person's words, so a request has to be read without it; a block that is never
 * closed is left alone, since the rest then cannot be trusted to be the person's.
 */
export const stripInjected = (text: string): string => {
  let rest = text
  for (;;) {
    const head = rest.trimStart()
    if (!head.startsWith(REMINDER_OPEN)) break
    const end = head.indexOf(REMINDER_CLOSE)
    if (end < 0) return text
    rest = head.slice(end + REMINDER_CLOSE.length)
  }

  return rest.trim()
}

/** How much of the previous window's last assistant reply the handoff carries. */
const LAST_REPLY_CHARS = 6_000

/** What the model reads when a switch is approved: it has to end the turn now. */
const APPROVED =
  '已批准换窗口。请立即结束本回合：不要再调用任何工具，用一句话说明你停在哪里即可。'

/** Activities kept in memory (and in meta): enough for the working set, not the whole session. */
const MAX_ACTIVITIES = 500

/** Subagents kept for the handoff; past this the oldest are dropped, which keeps meta.json small. */
const MAX_ROSTER = 50

/**
 * A request rebuilt the cache when it read under this share of the request before it,
 * and by more than the minimum: a small drop in a small window is not a rebuild.
 */
const REBUILT_READ_SHARE = 0.9
const REBUILT_MIN_DROP = 5_000

/** The assumptions used when a session has never switched and cannot say what its prefix costs. */
const DEFAULT_PREFIX = 30_000
const DEFAULT_HANDOFF = 8_000

/** The requests assumed to remain when the model does not say more work is coming. */
const REMAINING_REQUESTS = 100
const REMAINING_REQUESTS_LAST = 5

/** How many ledger entries one query may return. */
const MAX_QUERY_HITS = 30

/** How many windows a default history search covers. */
const SEARCH_WINDOWS = 3

const STATUS_LABEL: Record<TaskStatus, string> = {
  in_progress: '进行中',
  done: '已完成',
  superseded: '已被取代',
  blocked: '受阻',
}

type State = {
  window: number
  part: number
  seq: number
  ledgerSeq: number
  switchTimes: number[]
  requestsSinceSwitch: number
  /** Only remembered in memory: a reloaded session has no live turn to measure the cache against. */
  lastRequestAt: number | null
  reminded: { boundary: boolean; soft: boolean; urgent: boolean }
  archive: ArchivePage[]
  activities: FileActivity[]
  roster: AgentSeen[]
  /** Tool group -> the tokens its first load rewrote, the latest such load's; persisted, so a reloaded session still knows. */
  costlyLoads: Record<string, number>
  /** Groups a ToolSearch loaded since the last main-loop request: not persisted, judged by the next request's usage. */
  pendingLoads: string[]
  /** The main loop's last request context (input + read + write); not persisted. Null at a window's start. */
  lastContext: number | null
  /** Groups the gate has held back in this window: each is held back once, the second try goes through. Not persisted. */
  gateAsked: string[]
  /** Groups the gate held back and no load has taken yet: a switch made now is for them. Not persisted. */
  gateWanted: string[]
  lastPrefix: number | null
  lastHandoff: number | null
  /** The current ledger page, exactly what ledger.jsonl holds. */
  page: LedgerEntry[]
  pending: Pending | null
}

export type Session = {
  record: (row: RecordInput) => Promise<HistoryRecord>
  activity: (tool: string, input: Readonly<Record<string, unknown>>, seq: number, isError: boolean) => void
  noteRequest: () => void
  reminder: (env: Env) => string | null
  ledgerAppend: (input: unknown, env: Env) => Promise<ToolResult>
  ledgerRead: (input: unknown) => Promise<ToolResult>
  historyTool: (input: unknown) => Promise<ToolResult>
  /** The history write-amplification counters as one line, for the context tool's status. */
  historyWriteStats: () => string
  status: (env: Env) => string
  requestSwitch: (input: unknown, env: Env) => ToolResult
  /**
   * Holds back a ToolSearch that would load a costly group while the context is large: the
   * returned text sends the model to switch windows first. `null` lets the call through.
   * `await ready()` first.
   */
  gateLoad: (query: unknown, tokens: number | undefined) => string | null
  /** Loads the files and the recent requests: `await` it before the sync readers. */
  ready: () => Promise<void>
  /** The switch the model is waiting for, if any; `await ready()` is not needed (memory only). */
  pending: () => Pending | null
  blocksCalls: () => boolean
  clearPending: () => void
  /** Copies a conversation that predates this mod; a no-op once anything is on disk. */
  importMessages: (messages: readonly ImportedMessage[]) => Promise<number>
  buildHandoff: (opts: { isMidTurn: boolean; agents?: readonly AgentNote[] }) => Promise<string>
  commitSwitch: (info: { trigger: string; tokensBefore: number | undefined; handoffText: string }) => Promise<void>
  notePrefix: (tokens: number) => void
  /** The window the conversation is in; `await ready()` first, or it reads 1. */
  window: () => number
  /** Waits for the queued writes, then retries once whatever failed to write. */
  flush: () => Promise<void>
  /** The files (names only, sorted) whose last write failed and has not succeeded since. */
  unsaved: () => string[]
  /**
   * Keeps a user's message on disk before it is held back, so a reload cannot lose it. Resolves to
   * the item's id, or null when the write failed and the message must not be held.
   */
  hold: (text: string) => Promise<number | null>
  /** The held messages, oldest first; `await ready()` first. */
  heldItems: () => { id: number; text: string; at: number }[]
  /** Drops one held message and writes the rest back; an unknown id changes nothing. */
  release: (id: number) => Promise<void>
  /** The latest person prompt's seq; `await ready()` first. */
  latestPersonSeq: () => number | null
  /** The latest hand-off's seq (a coordinator's or a schedule's, never a person's); `await ready()` first. */
  latestRelaySeq: () => number | null
  /** Whether the ledger gained an entry after the latest person prompt of this window; `await ready()` first. */
  isLedgerFresh: () => boolean
  /** Whether a compaction may skip the engine's summary: a fresh ledger with a short unrecorded tail; `await ready()` first. */
  canSkipSummary: () => boolean
  /** The time of the last noted request, or null before the first one; `await ready()` first. */
  lastRequestAt: () => number | null
  /** Notes a subagent the main loop started, by id; a repeat of the id updates its row. `await ready()` is not needed. */
  noteAgent: (input: { id: string; type: string; description: string; model?: string; name?: string }) => Promise<void>
  /** Tags a noted subagent as ended and stamps when; an id never noted changes nothing. */
  agentEnded: (id: string) => Promise<void>
  /** Records a noted subagent's latest request size (kept in memory until its turn ends); an id never noted changes nothing. */
  agentStep: (id: string, tokens: number) => Promise<void>
  /** A SendMessage is about to resume a noted subagent: it runs again from now. Unknown recipients change nothing. */
  agentResumed: (to: string) => Promise<void>
  /**
   * Whether a SendMessage to `to` (an id or a name) should be held back once: the recipient is a noted,
   * ended subagent, idle past the cold limit, whose last request was large. Returns the Chinese notice,
   * or null to let it through (including the repeat of a held-back send).
   */
  coldResend: (to: string, message: string) => Promise<string | null>
  /** Reads one main-loop request's usage: a request right after a deferred load that rewrote the cache names that load's group. `await ready()` is not needed. */
  noteStep: (usage: { input: number; read: number; write: number }) => Promise<void>
  /** The costly groups this session judges by: the cross-session table with this session's own measures on top. `await ready()` first. */
  costlyGroups: () => Record<string, number>
}

const emptyState = (): State => ({
  window: 1,
  part: 0,
  seq: 0,
  ledgerSeq: 0,
  switchTimes: [],
  requestsSinceSwitch: 0,
  lastRequestAt: null,
  reminded: { boundary: false, soft: false, urgent: false },
  archive: [],
  activities: [],
  roster: [],
  costlyLoads: {},
  pendingLoads: [],
  lastContext: null,
  gateAsked: [],
  gateWanted: [],
  lastPrefix: null,
  lastHandoff: null,
  page: [],
  pending: null,
})

const errorOf = (result: string): ToolResult => ({ isError: true, result })

/** The message of whatever a failing `io.read` threw, whatever shape it had. */
const messageOf = (problem: unknown): string => {
  if (problem instanceof Error) return problem.message
  if (typeof problem === 'string') return problem

  return ''
}

const asInt = (value: unknown, fallback: number): number =>
  typeof value === 'number' && Number.isFinite(value) ? Math.max(0, Math.floor(value)) : fallback

const asNumberArray = (value: unknown): number[] =>
  Array.isArray(value) ? value.filter((item): item is number => typeof item === 'number') : []

const asRecordArray = <T>(value: unknown): T[] => (Array.isArray(value) ? (value as T[]) : [])

/** One roster row as meta.json holds it, or null when it lacks what a row needs. */
const seenOf = (value: unknown): AgentSeen | null => {
  if (typeof value !== 'object' || value === null) return null
  const row = value as Record<string, unknown>
  if (typeof row.id !== 'string' || typeof row.type !== 'string' || typeof row.description !== 'string') return null
  if (typeof row.window !== 'number' || !Number.isFinite(row.window)) return null
  if (typeof row.ts !== 'number' || !Number.isFinite(row.ts)) return null

  return {
    id: row.id,
    type: row.type,
    description: row.description,
    ...(typeof row.model === 'string' ? { model: row.model } : {}),
    window: row.window,
    ts: row.ts,
    ...(row.ended === true ? { ended: true } : {}),
    ...(typeof row.name === 'string' && row.name !== '' ? { name: row.name } : {}),
    ...(typeof row.lastActiveAt === 'number' && Number.isFinite(row.lastActiveAt) ? { lastActiveAt: row.lastActiveAt } : {}),
    ...(typeof row.contextTokens === 'number' && Number.isFinite(row.contextTokens) && row.contextTokens >= 0
      ? { contextTokens: row.contextTokens }
      : {}),
  }
}

/** A meta.json from before the roster has none, which reads as an empty roster; a damaged row is dropped alone. */
const rosterFrom = (value: unknown): AgentSeen[] =>
  (Array.isArray(value) ? value : []).map(seenOf).filter((seen): seen is AgentSeen => seen !== null).slice(-MAX_ROSTER)

/**
 * The costly loads as meta.json holds them. A meta.json from before the measure has
 * none, and a damaged entry is dropped alone: only a finite, positive count is a rewrite.
 */
const costlyFrom = (value: unknown): Record<string, number> => {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return {}
  const costly: Record<string, number> = {}
  for (const [name, rewritten] of Object.entries(value)) {
    if (typeof rewritten === 'number' && Number.isFinite(rewritten) && rewritten > 0) costly[name] = rewritten
  }

  return costly
}

/** One group's measure as the cross-session table holds it; a hand-written entry may leave `context` out. */
type SharedCost = { write: number; context?: number; at: number }

/** Where the cross-session measures are: the older shared table, and each session's own file under one directory. */
type SharedPaths = { legacy: string; own: string; shards: string }

/**
 * The paths of the cross-session measures: one level above this session's directory, so every
 * session under the same mod directory reads the same measures. Each session only ever writes its
 * own file, so no two writers share one. A root with no slash has no parent, and then there are none.
 */
const sharedPathsOf = (root: string): SharedPaths | null => {
  const cut = root.lastIndexOf('/')
  if (cut < 0) return null
  const dir = root.slice(0, cut)
  const shards = `${dir}/${SHARED_DIR}`

  return { legacy: `${dir}/${COSTLY_FILE}`, own: `${shards}/${root.slice(cut + 1)}.json`, shards }
}

/**
 * The table as the file holds it, keeping only the measures that are a finite positive
 * rewrite stamped within the expiry. A missing or damaged file is an empty table, never a throw.
 */
const sharedFrom = (text: string | null, now: number): Record<string, SharedCost> => {
  const table: Record<string, SharedCost> = {}
  if (text === null) return table
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return table
  }
  const groups =
    typeof parsed === 'object' && parsed !== null ? (parsed as Record<string, unknown>).groups : undefined
  if (typeof groups !== 'object' || groups === null || Array.isArray(groups)) return table
  for (const [name, value] of Object.entries(groups)) {
    if (typeof value !== 'object' || value === null) continue
    const { write, context, at } = value as Record<string, unknown>
    if (typeof write !== 'number' || !Number.isFinite(write) || write <= 0) continue
    if (typeof at !== 'number' || !Number.isFinite(at) || now - at > SHARED_MS) continue
    table[name] = {
      write,
      ...(typeof context === 'number' && Number.isFinite(context) ? { context } : {}),
      at,
    }
  }

  return table
}

/**
 * The table as the file holds it, or null when it is there but cannot be trusted: unreadable is
 * not the same as empty, and a file that cannot be trusted is never written over.
 */
const tableOf = (text: string | null | undefined, now: number): Record<string, SharedCost> | null => {
  if (text === null) return {}
  if (text === undefined) return null
  try {
    const parsed: unknown = JSON.parse(text)
    const groups = typeof parsed === 'object' && parsed !== null ? (parsed as { groups?: unknown }).groups : undefined
    if (typeof groups !== 'object' || groups === null || Array.isArray(groups)) return null
  } catch {
    return null
  }

  return sharedFrom(text, now)
}

/** Keeps, for each group, the newer of the two measures: the last one written wins whichever file holds it. */
const newerInto = (into: Record<string, SharedCost>, from: Record<string, SharedCost>): void => {
  for (const [name, cost] of Object.entries(from)) {
    const held = into[name]
    if (held === undefined || held.at < cost.at) into[name] = cost
  }
}

/**
 * Every measure the sessions have written, and this session's own file. A file that cannot be read
 * is left out; a session's own file that cannot be trusted comes back as null, so it is not written over.
 */
const readShared = async (
  io: Io,
  paths: SharedPaths,
): Promise<{ table: Record<string, SharedCost>; own: Record<string, SharedCost> | null }> => {
  const now = io.now()
  const table = tableOf(await readAt(io, paths.legacy), now) ?? {}
  let names: readonly string[] = []
  if (io.list !== undefined) {
    try {
      names = await io.list(paths.shards)
    } catch {
      names = []
    }
  }
  for (const name of names) {
    if (!name.endsWith('.json')) continue
    newerInto(table, tableOf(await readAt(io, `${paths.shards}/${name}`), now) ?? {})
  }
  const own = tableOf(await readAt(io, paths.own), now)
  newerInto(table, own ?? {})

  return { table, own }
}

/**
 * The file's text: null when the file is absent, undefined when it cannot be read though it may be
 * there. Only an absent file is empty; one that failed to read must not be written over.
 */
const readAt = async (io: Io, path: string): Promise<string | null | undefined> => {
  try {
    return await io.read(path)
  } catch (problem) {
    const isGone = io.exists === undefined ? isMissingError(problem) : !(await io.exists(path).catch(() => true))

    return isGone ? null : undefined
  }
}

/** Whether a failed read says the file is simply not there (as opposed to unreadable). */
const isMissingError = (error: unknown): boolean => {
  if (typeof error !== 'object' || error === null) return false
  const { code, message } = error as { code?: unknown; message?: unknown }
  if (code === 'ENOENT' || code === 'ENOTDIR') return true

  return typeof message === 'string' && /ENOENT|no such file|not found|does not exist/i.test(message)
}

const sharedJson = (table: Record<string, SharedCost>): string => JSON.stringify({ version: 1, groups: table })

/** A tool use's arguments, as the activity reader and the path reader both want them. */
const asInput = (value: unknown): Readonly<Record<string, unknown>> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {}

/** The file a tool call named, in the order the engine's own tools spell it. */
const pathOf = (input: Readonly<Record<string, unknown>>): string | undefined => {
  for (const key of ['file_path', 'notebook_path', 'path']) {
    if (typeof input[key] === 'string') return input[key] as string
  }

  return undefined
}

const k = (tokens: number): number => Math.round(tokens / 1000)

/** A damaged meta.json is an empty session, never a throw. */
/** The handoff a window opened with; every switch writes one, so it also marks that the window exists. */
const handoffName = (window: number): string => `handoff-w${String(window).padStart(3, '0')}.md`

const stateFrom = (raw: Record<string, unknown> | null): State => {
  const state = emptyState()
  if (raw === null) return state

  state.window = Math.max(1, asInt(raw.window, 1))
  state.part = asInt(raw.part, 0)
  state.seq = asInt(raw.seq, 0)
  state.ledgerSeq = asInt(raw.ledgerSeq, 0)
  state.switchTimes = asNumberArray(raw.switchTimes)
  state.requestsSinceSwitch = asInt(raw.requestsSinceSwitch, 0)
  state.lastRequestAt = typeof raw.lastRequestAt === 'number' && Number.isFinite(raw.lastRequestAt) ? raw.lastRequestAt : null
  state.archive = asRecordArray<ArchivePage>(raw.archive)
  state.activities = asRecordArray<FileActivity>(raw.activities)
  state.roster = rosterFrom(raw.roster)
  state.costlyLoads = costlyFrom(raw.costlyLoads)
  state.lastPrefix = typeof raw.lastPrefix === 'number' ? raw.lastPrefix : null
  state.lastHandoff = typeof raw.lastHandoff === 'number' ? raw.lastHandoff : null
  const reminded = typeof raw.reminded === 'object' && raw.reminded !== null ? (raw.reminded as Record<string, unknown>) : {}
  state.reminded = {
    boundary: reminded.boundary === true,
    soft: reminded.soft === true,
    urgent: reminded.urgent === true,
  }

  return state
}

/** The minutes a noted subagent has been idle; a row from before the stamp counts from its spawn. */
const idleMinutesOf = (seen: AgentSeen, now: number): number =>
  Math.max(0, now - (seen.lastActiveAt ?? seen.ts)) / 60_000

/** An idle time spelled for a person: minutes under an hour, hours (one decimal under ten) from there. */
const idleText = (minutes: number): string => {
  if (minutes < 60) return `${Math.round(minutes)} 分钟`
  const hours = minutes / 60

  return hours < 10 ? `${Math.round(hours * 10) / 10} 小时` : `${Math.round(hours)} 小时`
}

/** What the handoff says of an ended subagent's cache: cold past the limit, otherwise possibly still hot. */
const cacheNoteOf = (seen: AgentSeen, now: number, config: Config): string => {
  const minutes = idleMinutesOf(seen, now)
  const size = rewriteOf(seen.contextTokens ?? 0)
  if (minutes > config.agentColdMinutes) return `闲置 ${idleText(minutes)}，缓存已冷，${size} token`

  return `闲置 ${idleText(minutes)}，缓存可能仍热，${size} token`
}

/**
 * The subagents the handoff names: the engine's live list as it gave it, then the
 * noted ones it no longer lists, as ended and newest first. An id both sides hold
 * keeps the engine's row, so each agent is named once.
 */
const agentsForHandoff = (
  live: readonly AgentNote[],
  roster: readonly AgentSeen[],
  now: number,
  config: Config,
): AgentNote[] => {
  const listed = new Set(live.map(agent => agent.id))
  const ended = roster
    .filter(seen => !listed.has(seen.id))
    .sort((left, right) => right.ts - left.ts)
    .map(
      (seen): AgentNote => ({
        id: seen.id,
        type: seen.type,
        description: seen.description,
        state: ENDED_STATE,
        ...(seen.contextTokens === undefined ? {} : { cache: cacheNoteOf(seen, now, config) }),
      }),
    )

  return [...live, ...ended]
}

/**
 * The deferred tools the window loaded and used whose first load rebuilt the cache,
 * each with the tokens it rewrote. A group no request has measured is left out: the
 * handoff advises only the loads that cost the whole cached prefix.
 */
const costlyToolsOf = (tools: readonly LoadedTool[], costly: Record<string, number>): RebuiltTool[] =>
  tools.flatMap(tool => {
    if (!Object.hasOwn(costly, tool.name)) return []
    const rebuilt = costly[tool.name]

    return rebuilt === undefined ? [] : [{ name: tool.name, calls: tool.calls, rebuilt }]
  })

/** The most unrecorded steps the handoff lists one by one. */
const MAX_TAIL_ACTIONS = 25

export const createSession =(dir: string, io: Io, config: Config): Session => {
  const root = dir.replace(/\/+$/, '')
  const pathIn = (name: string): string => `${root}/${name}`
  /**
   * Paths whose last write failed, with the text that did not land: a read that comes
   * back empty can say why, and `flush` can try the same content once more.
   */
  const failedWrites = new Map<string, string>()
  /** Writes through to the engine, keeping the failure visible to the readers. */
  const writeThrough = async (path: string, text: string): Promise<void> => {
    try {
      await io.write(path, text)
      failedWrites.delete(path)
    } catch (problem) {
      failedWrites.set(path, text)
      try {
        io.onWriteError?.(path, problem)
      } catch {
        // A reporter that throws must not change how the write fails.
      }

      throw problem
    }
  }
  /**
   * What the history writes cost, in memory only: the bytes the new rows add and the
   * bytes the shard files actually took. Nothing here changes a write; it only counts.
   */
  const writeStats = { logicalNewBytes: 0, physicalBytesWritten: 0, writeCalls: 0, coalesced: 0 }
  const isShardPath = (path: string): boolean => /(?:^|[\\/])history-[^\\/]+(?:\.jsonl|\.manifest\.json)$/.test(path)
  const queue = createQueue(writeThrough, undefined, {
    onWrite: (path, bytes) => {
      if (!isShardPath(path)) return
      writeStats.physicalBytesWritten += bytes
      writeStats.writeCalls += 1
    },
    onCoalesce: path => {
      if (!isShardPath(path)) return
      writeStats.coalesced += 1
    },
  })
  const state = emptyState()
  /** Every shard this session has in memory, the current one included: old windows stay searchable. */
  const shards = new Map<string, Shard>()
  /** Windows whose every part is in `shards`. */
  const fullWindows = new Set<number>()
  /** The segment each window's newest rows are in, so the next record can join it. */
  const activeSegments = new Map<number, string>()
  /** A segment rolls at either limit; one record larger than the byte cap still lands alone. */
  const segmentRecords = Math.max(1, Math.floor(config.segmentRecords))
  const segmentBytes = Math.max(1, config.segmentBytes)

  /** Whether `io.list` works here; null until a load has tried it. */
  let listWorks: boolean | null = null
  /** How often the manifest is refreshed when no directory listing is available. */
  const MANIFEST_EVERY = 64

  /** The directory's file names, or null when this host cannot list it. */
  const listDir = async (): Promise<readonly string[] | null> => {
    if (typeof io.list !== 'function') {
      listWorks = false

      return null
    }
    try {
      const names = await io.list(root)
      listWorks = true

      return names
    } catch {
      listWorks = false

      return null
    }
  }

  /** Adds one segment file to memory, and says whether it was there. */
  const addSegment = async (window: number, seq: number): Promise<boolean> => {
    const name = segmentName(window, seq)
    if (shards.has(name)) return true
    const text = await readText(pathIn(name))
    if (text === null) return false
    shards.set(name, { window, part: 0, rows: parseHistoryText(text), bytes: byteLength(text) })
    const active = activeSegments.get(window)
    if (active === undefined || seq > (segmentSeq(active, window) ?? 0)) activeSegments.set(window, name)

    return true
  }

  /**
   * Reads a window's append-format segments. A directory listing is authoritative
   * when the host has one. Without it the manifest gives the range, and the seqs
   * just past it are probed because meta.json is written after every row and may
   * be newer; with neither, the newest seq meta.json names is probed backwards.
   */
  const readSegments = async (window: number): Promise<void> => {
    const manifestText = await readText(pathIn(manifestName(window)))
    const manifest = manifestText === null ? null : parseManifest(manifestText, window)
    if (manifest !== null) {
      if (manifest.version === 2 && manifest.segments !== undefined) {
        for (const seq of manifest.segments) await addSegment(window, seq)
      } else {
        // A v1 manifest held one record per segment, so every seq in its range is a start.
        for (let seq = manifest.firstSeq; seq <= manifest.lastSeq; seq += 1) await addSegment(window, seq)
      }
    }

    const names = await listDir()
    if (names !== null) {
      const seqs = names
        .map(name => segmentSeq(name, window))
        .filter((seq): seq is number => seq !== null)
        .sort((left, right) => left - right)
      for (const seq of seqs) await addSegment(window, seq)

      return
    }

    if (manifest !== null) {
      // The active segment may have grown, and a newer one may have started, after
      // the manifest was written: read the known segments, then probe past their rows.
      let misses = 0
      for (let seq = topSeqOf(window) + 1; misses < 8; seq += 1) {
        if (await addSegment(window, seq)) misses = 0
        else misses += 1
      }

      return
    }

    // No manifest and no listing: walk back from the newest seq. A segment starts
    // at its first row, so the gap to the previous start is at most the record cap.
    let misses = 0
    const missLimit = segmentRecords + 2
    for (let seq = state.seq; seq >= 1 && misses < missLimit; seq -= 1) {
      if (await addSegment(window, seq)) misses = 0
      else misses += 1
    }
  }

  /** Writes down the window's segment starts, so a host without a listing can find it after a crash. */
  const saveManifest = (window: number): void => {
    let firstSeq = 0
    let lastSeq = 0
    let count = 0
    const segments: number[] = []
    for (const [name, shard] of shards) {
      if (shard.window !== window) continue
      const start = segmentSeq(name, window)
      if (start !== null) segments.push(start)
      for (const row of shard.rows) {
        if (!Number.isInteger(row.seq) || row.seq < 1) continue
        if (firstSeq === 0 || row.seq < firstSeq) firstSeq = row.seq
        if (row.seq > lastSeq) lastSeq = row.seq
        count += 1
      }
    }
    if (count === 0) return
    segments.sort((left, right) => left - right)
    void queue.push(
      pathIn(manifestName(window)),
      JSON.stringify({ version: 2, window, firstSeq, lastSeq, count, segments }),
    )
  }
  const archives = new Map<number, LedgerEntry[]>()
  /**
   * The events file as this session knows it. Its own reads go straight to the
   * disk and miss a write still queued, so every switch appends to this text.
   */
  let eventsText: string | null = null
  /** Where the cross-session measures are, or null when this session's directory has no parent to hold them. */
  const shared = sharedPathsOf(root)
  /** The measures as this session last read or wrote them: never persisted, read again at each load. */
  let sharedCostly: Record<string, SharedCost> = {}
  /** This session's own measures as its file holds them; null when that file cannot be trusted, so it is not written. */
  let ownCostly: Record<string, SharedCost> | null = {}
  /** The messages held back and not yet delivered, as held.json has them. */
  let held: HeldItem[] = []
  const heldJson = (): string => JSON.stringify({ items: held })

  const readText = async (path: string): Promise<string | null> => {
    try {
      return await io.read(path)
    } catch {
      // Absent, unreadable or too large: every caller here treats them the same.
      return null
    }
  }

  const allRows = (): HistoryRecord[] => {
    const rows: HistoryRecord[] = []
    for (const shard of shards.values()) rows.push(...shard.rows)

    return rows.sort((left, right) => left.seq - right.seq)
  }

  const bySeq = (seq: number): HistoryRecord | undefined => {
    for (const shard of shards.values()) {
      const found = shard.rows.find(row => row.seq === seq)
      if (found !== undefined) return found
    }

    return undefined
  }

  const latestPersonRow = (): HistoryRecord | null => {
    let best: HistoryRecord | null = null
    for (const shard of shards.values()) {
      for (const row of shard.rows) {
        if (row.isPerson !== true) continue
        if (best === null || row.seq > best.seq) best = row
      }
    }

    return best
  }

  /** The latest hand-off among the loaded rows: a task's source in a session no person started. */
  const latestRelayRow = (): HistoryRecord | null => {
    let best: HistoryRecord | null = null
    for (const shard of shards.values()) {
      for (const row of shard.rows) {
        if (!isRelay(row)) continue
        if (best === null || row.seq > best.seq) best = row
      }
    }

    return best
  }

  const latestAssistantRow = (): HistoryRecord | null => {
    let best: HistoryRecord | null = null
    for (const shard of shards.values()) {
      for (const row of shard.rows) {
        // A row with a door is the engine's delivery or note, never the model's own reply.
        if (row.role !== 'assistant' || row.door !== undefined) continue
        if (best === null || row.seq > best.seq) best = row
      }
    }

    return best
  }

  const metaJson = (): string =>
    JSON.stringify({
      window: state.window,
      part: state.part,
      seq: state.seq,
      ledgerSeq: state.ledgerSeq,
      switchTimes: state.switchTimes,
      requestsSinceSwitch: state.requestsSinceSwitch,
      reminded: state.reminded,
      archive: state.archive,
      activities: state.activities,
      roster: state.roster,
      costlyLoads: state.costlyLoads,
      lastRequestAt: state.lastRequestAt,
      lastPrefix: state.lastPrefix,
      lastHandoff: state.lastHandoff,
    })

  /** Only ever writes what is loaded: saving before the load would erase the file. */
  const saveMeta = (): void => {
    if (!loaded) return
    void queue.push(pathIn('meta.json'), metaJson())
  }

  /**
   * Reads one window's shards from part 0 up to the first absent part, and says
   * how many there were. A shard's size says nothing about a later part: a
   * rotation happens before the ceiling is reached, so a rotated shard is
   * always under it.
   */
  const readWindow = async (window: number): Promise<number> => {
    let parts = 0
    for (; ; parts += 1) {
      const name = shardName(window, parts)
      const text = await readText(pathIn(name))
      if (text === null) break
      shards.set(name, { window, part: parts, rows: parseHistoryText(text), bytes: byteLength(text) })
    }

    await readSegments(window)

    return parts
  }

  const loadWindow = async (window: number): Promise<void> => {
    if (fullWindows.has(window)) return
    await readWindow(window)
    fullWindows.add(window)
  }

  /** The highest seq among one window's rows in memory, or 0 when it has none. */
  const topSeqOf = (window: number): number => {
    let top = 0
    for (const shard of shards.values()) {
      if (shard.window !== window) continue
      for (const row of shard.rows) {
        if (Number.isInteger(row.seq) && row.seq > top) top = row.seq
      }
    }

    return top
  }

  const loadArchive = async (page: number): Promise<LedgerEntry[] | null> => {
    const cached = archives.get(page)
    if (cached !== undefined) return cached
    const text = await readText(pathIn(archiveName(page)))
    if (text === null) return null
    const entries = parseJsonl<LedgerEntry>(text)
    archives.set(page, entries)

    return entries
  }

  const load = async (): Promise<void> => {
    const text = await readText(pathIn('meta.json'))
    let raw: Record<string, unknown> | null = null
    if (text !== null) {
      try {
        const parsed: unknown = JSON.parse(text)
        raw = typeof parsed === 'object' && parsed !== null ? (parsed as Record<string, unknown>) : null
      } catch {
        raw = null
      }
    }
    Object.assign(state, stateFrom(raw))

    // meta.json is written after the files it describes and can be lost, stale
    // or damaged, so the files have the last word on everything they can tell:
    // the window, the part, the seq and the archive pages. A seq or an archive
    // page handed out twice would make one name mean two things.
    for (;;) {
      const next = state.window + 1
      const isOpened =
        (await readText(pathIn(handoffName(next)))) !== null ||
        (await readText(pathIn(shardName(next, 0)))) !== null ||
        (await readText(pathIn(manifestName(next)))) !== null
      if (!isOpened) break
      state.window = next
      state.requestsSinceSwitch = 0
      state.reminded = { boundary: false, soft: false, urgent: false }
    }

    state.part = Math.max(0, (await readWindow(state.window)) - 1)
    fullWindows.add(state.window)
    // A window that was only just opened has no row yet; the seq is then in an earlier one.
    let top = topSeqOf(state.window)
    for (let window = state.window - 1; top === 0 && window >= 1; window -= 1) {
      await loadWindow(window)
      top = topSeqOf(window)
    }
    state.seq = Math.max(state.seq, top)

    const ledgerText = await readText(pathIn('ledger.jsonl'))
    state.page = ledgerText === null ? [] : parseJsonl<LedgerEntry>(ledgerText)
    for (const entry of state.page) state.ledgerSeq = Math.max(state.ledgerSeq, entry.seq)
    for (let page = state.archive.length + 1; ; page += 1) {
      const entries = await loadArchive(page)
      if (entries === null) break
      state.archive.push(pageOf(page, entries))
      for (const entry of entries) state.ledgerSeq = Math.max(state.ledgerSeq, entry.seq)
    }
    // Another session may have measured a group this one has not met, so the whole table is read.
    if (shared !== null) {
      const loaded = await readShared(io, shared)
      sharedCostly = loaded.table
      ownCostly = loaded.own
    }
    held = heldFrom(await readText(pathIn(HELD_FILE)))
  }

  let loading: Promise<void> | null = null
  let loaded = false
  const ensureLoaded = (): Promise<void> => {
    if (loading === null) {
      loading = load().then(() => {
        loaded = true
      })
    }

    return loading
  }

  /**
   * What every synchronous reader below needs in memory: the files, and the
   * recent person requests that may sit in an earlier window.
   */
  const ready = async (): Promise<void> => {
    await ensureLoaded()
    await ensureRequests()
  }

  /**
   * Pulls older windows in until every referenced seq and at least one person
   * prompt are in memory, so `ledger.validate` can look the whole session up.
   */
  const ensureHistory = async (seqs: readonly number[]): Promise<void> => {
    const wanted = [...new Set(seqs.filter(seq => Number.isInteger(seq) && seq > 0))]
    for (let window = state.window - 1; window >= 1; window -= 1) {
      if (wanted.every(seq => bySeq(seq) !== undefined) && latestPersonRow() !== null) break
      await loadWindow(window)
    }
  }

  /**
   * Pulls older windows in until the most recent person prompts are in memory:
   * a reloaded session holds only the current window's shard, and the handoff,
   * the page turn and the home view all have to name the requests of the session.
   */
  const ensureRequests = async (): Promise<void> => {
    for (let window = state.window - 1; window >= 1; window -= 1) {
      if (personRequests(allRows(), config.recentRequests).length >= config.recentRequests) break
      await loadWindow(window)
    }
  }

  /**
   * Pulls older windows in until each recent request has the reply it came after in
   * memory. That reply sits in the request's own window or the one before, so the
   * session's very first request never drags every window in.
   */
  const ensureAnswered = async (): Promise<void> => {
    for (let window = state.window - 1; window >= 1; window -= 1) {
      const rows = allRows()
      const requests = personRequests(rows, config.recentRequests)
      const answered = repliesAnswered(rows, requests)
      if (requests.every(request => answered.has(request.seq) || request.window - 1 > window)) break
      await loadWindow(window)
    }
  }

  /**
   * Pulls older windows in until the last assistant reply is in memory: a
   * reloaded session holds only the current window's shard, and the handoff has
   * to carry what the model last concluded.
   */
  const ensureReplies = async (): Promise<void> => {
    for (let window = state.window - 1; window >= 1; window -= 1) {
      if (latestAssistantRow() !== null) break
      await loadWindow(window)
    }
  }

  /**
   * The hand-off the open work came from, for the home page: the one an open
   * task points at, else, in a session no person has spoken in, the latest one.
   */
  const relayForHome = async (): Promise<HistoryRecord | undefined> => {
    const refs = tasksOf(state.page)
      .filter(task => task.status === 'in_progress' || task.status === 'blocked')
      .flatMap(task => task.entries.map(entry => entry.request_ref))
    await ensureHistory(refs)
    let best: HistoryRecord | undefined
    for (const seq of refs) {
      const row = bySeq(seq)
      if (row !== undefined && isRelay(row) && (best === undefined || row.seq > best.seq)) best = row
    }
    if (best === undefined && latestPersonRow() === null) best = latestRelayRow() ?? undefined

    return best === undefined ? undefined : displayRequests([best])[0]
  }

  /** The last thing the model said, cut to its tail when it is too long to carry. */
  const lastReplyOf = (): string | null => {
    const row = latestAssistantRow()
    if (row === null) return null
    if (row.text.length <= LAST_REPLY_CHARS) return row.text

    return `（前文已省略，用 history 工具查看 #${row.seq}）\n${row.text.slice(row.text.length - LAST_REPLY_CHARS)}`
  }




  const record = async (row: RecordInput): Promise<HistoryRecord> => {
    await ensureLoaded()
    const seq = state.seq + 1
    const full: HistoryRecord = {
      seq,
      uuid: row.uuid,
      ts: io.now(),
      window: state.window,
      role: row.role,
      text: row.text,
    }
    if (row.isPerson === true) full.isPerson = true
    if (row.origin !== undefined) full.origin = row.origin
    if (row.tool !== undefined) full.tool = row.tool
    if (row.path !== undefined) full.path = row.path
    if (row.input !== undefined) full.input = row.input
    if (row.isError === true) full.isError = true
    if (row.loaded !== undefined) full.loaded = row.loaded
    if (row.door !== undefined) full.door = row.door
    if (row.name !== undefined) full.name = row.name
    if (row.args !== undefined) full.args = row.args
    if (row.callId !== undefined) full.callId = row.callId
    // A load is judged by the next request's usage, which says whether the cache was rebuilt.
    if (row.tool === 'ToolSearch' && row.loaded !== undefined) {
      for (const name of row.loaded) {
        const group = toolGroupOf(name)
        if (!state.pendingLoads.includes(group)) state.pendingLoads.push(group)
        // A group the model loaded itself, instead of switching first, no longer needs the switch.
        state.gateWanted = state.gateWanted.filter(wanted => wanted !== group)
      }
    }

    const clipped = clipRecord(full)
    // The row's own share of the shard, newline included: what the write would cost if the
    // whole file never had to be rewritten. Counted whether or not the write lands.
    writeStats.logicalNewBytes += byteLength(JSON.stringify(clipped)) + 1
    state.part = 0
    const rowBytes = byteLength(JSON.stringify(clipped)) + 1
    const active = activeSegments.get(state.window)
    const current = active === undefined ? undefined : shards.get(active)
    // A segment is rewritten whole each time it grows, so it is filled to its record
    // or byte cap first: fewer files to open later, the same bytes per record now.
    const joins =
      active !== undefined &&
      current !== undefined &&
      current.rows.length > 0 &&
      current.rows.length < segmentRecords &&
      current.bytes + rowBytes <= segmentBytes
    const name = joins && active !== undefined ? active : segmentName(state.window, seq)
    let rows: HistoryRecord[]
    if (joins && current !== undefined) {
      current.rows.push(clipped)
      current.bytes += rowBytes
      rows = current.rows
    } else {
      rows = [clipped]
      shards.set(name, { window: state.window, part: 0, rows, bytes: rowBytes })
      activeSegments.set(state.window, name)
    }
    fullWindows.add(state.window)
    state.seq = seq





    // The whole original of a clipped field goes out before the row that points at it. A part
    // that fails to land is kept by `writeThrough` like any other file, so `flush` retries it.
    for (const field of ['text', 'args'] as const) {
      if (clipped.overflow?.[field] === undefined) continue
      splitParts(field === 'text' ? full.text : full.args ?? '').parts.forEach((part, index) => {
        void queue.push(pathIn(overflowName(seq, field, index)), part)
      })
    }
    void queue.push(pathIn(name), toJsonl(rows))
    // A host that cannot list needs the manifest to find every roll; one that can
    // find the files itself only keeps the manifest fresh now and then.
    if (listWorks === false || seq % MANIFEST_EVERY === 0) saveManifest(state.window)
    saveMeta()

    return clipped
  }

  const activity = (tool: string, input: Readonly<Record<string, unknown>>, seq: number, isError: boolean): void => {
    const found = activityOf(tool, input, { seq, window: state.window, isError })
    if (found === null) return
    state.activities.push(found)
    if (state.activities.length > MAX_ACTIVITIES) {
      state.activities.splice(0, state.activities.length - MAX_ACTIVITIES)
    }
    // The activity is part of what the next window reads, so it has to be on disk
    // even when no further row is recorded this turn.
    saveMeta()
  }

  /**
   * Notes a subagent the main loop started. The engine lists an agent only while it
   * runs, yet SendMessage still reaches it by this id after it ends, so the handoff
   * has to keep its id, type and task. A repeat of the id updates the row instead.
   */
  const noteAgent = async (input: { id: string; type: string; description: string; model?: string; name?: string }): Promise<void> => {
    await ensureLoaded()
    const known = state.roster.find(seen => seen.id === input.id)
    if (known === undefined) {
      state.roster.push({
        id: input.id,
        type: input.type,
        description: input.description,
        ...(input.model === undefined ? {} : { model: input.model }),
        ...(input.name === undefined || input.name === '' ? {} : { name: input.name }),
        window: state.window,
        ts: io.now(),
        lastActiveAt: io.now(),
      })
      if (state.roster.length > MAX_ROSTER) state.roster.splice(0, state.roster.length - MAX_ROSTER)
    } else {
      known.type = input.type
      known.description = input.description
      if (input.model === undefined) delete known.model
      else known.model = input.model
      if (input.name !== undefined && input.name !== '') known.name = input.name
      known.lastActiveAt = io.now()
      delete known.ended
    }
    saveMeta()
  }

  /**
   * Tags a noted subagent as ended once its own turn completes. An id the roster
   * does not hold changes nothing, and a tag already set is not written again.
   */
  const agentEnded = async (id: string): Promise<void> => {
    await ensureLoaded()
    const known = state.roster.find(seen => seen.id === id)
    if (known === undefined) return
    known.ended = true
    known.lastActiveAt = io.now()
    saveMeta()
  }

  const agentStep = async (id: string, tokens: number): Promise<void> => {
    await ensureLoaded()
    const known = state.roster.find(seen => seen.id === id)
    if (known === undefined || !Number.isFinite(tokens) || tokens <= 0) return
    // Kept in memory: the turn's end writes it, so a step does not cost a write.
    known.contextTokens = Math.round(tokens)
    known.lastActiveAt = io.now()
  }

  /** The roster row a SendMessage recipient names: by id, else by the Agent call's name (a trailing ` [ref]` is not part of it). */
  const seenFor = (to: string): AgentSeen | undefined => {
    const wanted = to.trim().replace(/\s*\[[^\]]*\]$/, '')
    if (wanted === '') return undefined

    return state.roster.find(seen => seen.id === wanted) ?? state.roster.find(seen => seen.name === wanted)
  }

  /** Recipient id -> the hold-back it last got: the repeat of that message, or any within the resend window, goes through. */
  const heldResends = new Map<string, { at: number; message: string }>()

  const agentResumed = async (to: string): Promise<void> => {
    await ensureLoaded()
    const known = seenFor(to)
    if (known === undefined) return
    known.lastActiveAt = io.now()
    delete known.ended
    saveMeta()
  }

  const coldResend = async (to: string, message: string): Promise<string | null> => {
    await ensureLoaded()
    const known = seenFor(to)
    if (known === undefined || known.ended !== true) return null
    const now = io.now()
    const held = heldResends.get(known.id)
    if (held !== undefined) {
      heldResends.delete(known.id)
      if (held.message === message || now - held.at < config.agentResendMinutes * 60_000) return null
    }
    const minutes = idleMinutesOf(known, now)
    const tokens = known.contextTokens
    if (tokens === undefined || tokens <= config.agentColdMinTokens || minutes <= config.agentColdMinutes) return null
    heldResends.set(known.id, { at: now, message })

    return `子代理 ${known.name ?? known.id}（${known.type}）已闲置 ${idleText(minutes)}，提示缓存早已过期，续用第一轮要重写${rewriteOf(tokens)} token 的缓存。建议新建同类型代理，用它最后的报告加文件路径做短交接；若仍要续用，原样再发一次。`
  }

  /**
   * Judges the loads still waiting on the next main-loop request. Loading a tool group
   * changes the tool list the cached prefix was made over, so the first request after
   * a load reads far less from the cache than the request before it. A group loaded
   * again in the same window does not rebuild, so only the first load is recorded.
   */
  /**
   * Puts one measured group into the cross-session measures, in this session's own file: no other
   * session writes that file, so there is no lock. The file is written whole, from what this session
   * has recorded, and a file that could not be read at load is left as it is.
   */
  const recordShared = async (group: string, write: number, context: number): Promise<void> => {
    if (shared === null) return
    const file = shared.own
    const report = (problem: unknown): void => {
      try {
        io.onWriteError?.(file, problem)
      } catch {
        // A reporter that throws must not change how the write fails.
      }
    }
    if (ownCostly === null) {
      report(new Error('the session file could not be read or parsed: left as it is, this measure was not recorded'))

      return
    }
    const at = io.now()
    // Only this session writes this file, so it drops its own measures that have gone stale.
    const fresh = Object.fromEntries(Object.entries(ownCostly).filter(([, cost]) => at - cost.at <= SHARED_MS))
    const own = { ...fresh, [group]: { write, context, at } }
    try {
      const text = sharedJson(own)
      if (io.rename === undefined) {
        await io.write(file, text)
      } else {
        const temp = `${file}.${at}-${Math.random().toString(36).slice(2)}.tmp`
        await io.write(temp, text)
        try {
          await io.rename(temp, file)
        } catch (problem) {
          await io.remove?.(temp).catch(() => undefined)
          throw problem
        }
      }
      ownCostly = own
      sharedCostly = { ...sharedCostly, [group]: { write, context, at } }
    } catch (problem) {
      report(problem)
    }
  }

  const noteStep = async (usage: { input: number; read: number; write: number }): Promise<void> => {
    await ensureLoaded()
    const before = state.lastContext
    // A cache that expired on its own (the wait, not a load, emptied it) is no load's doing: nothing is recorded.
    const expired = isCold({ now: io.now(), cache: null, lastRequestAt: state.lastRequestAt }, config)
    // Two groups loaded in one step rewrote the cache together: neither can be blamed for it alone.
    if (!expired && state.pendingLoads.length === 1 && before !== null) {
      const rebuilt =
        usage.read < before * REBUILT_READ_SHARE && before - usage.read > REBUILT_MIN_DROP && usage.write > 0
      if (rebuilt) {
        for (const group of state.pendingLoads) {
          state.costlyLoads[group] = usage.write
          await recordShared(group, usage.write, before)
        }
        saveMeta()
      }
    }
    state.pendingLoads = []
    state.lastContext = usage.input + usage.read + usage.write
  }

  /**
   * The costly groups this session judges by: the table's measures, with this session's own
   * on top where both name a group. `await ready()` first, so the table is in memory.
   */
  const costlyGroups = (): Record<string, number> => {
    const groups: Record<string, number> = {}
    for (const [name, cost] of Object.entries(sharedCostly)) groups[name] = cost.write

    return { ...groups, ...state.costlyLoads }
  }

  /**
   * Where the part of the engine's conversation the mod has not recorded begins.
   * A message has no id of its own, so it is lined up with the rows by what it
   * carries: a tool call's id, the `[#n]` this mod appended to a result, and
   * last by its words (equal once whitespace is gone, or one inside the other
   * with the shorter at least a dozen characters). The last known message
   * wins; the words are compared only with rows after the last tool row found
   * by id, since earlier rows cannot belong to the tail.
   */
  const firstUnrecorded = (messages: readonly ImportedMessage[]): number => {
    const rows = allRows()
    const seqOfCall = new Map<string, number>()
    for (const row of rows) {
      if (row.role === 'tool' && row.callId !== undefined) seqOfCall.set(row.callId, row.seq)
    }
    let last = -1
    let anchor = 0
    messages.forEach((message, index) => {
      let hit = 0
      for (const use of message.toolUses) {
        const seq = use.callId === undefined ? undefined : seqOfCall.get(use.callId)
        if (seq !== undefined) hit = Math.max(hit, seq)
        const suffix = typeof use.text === 'string' ? /\[#(\d+)\]\s*$/.exec(use.text) : null
        const number = suffix === null ? 0 : Number(suffix[1])
        if (number >= 1 && number <= state.seq) hit = Math.max(hit, number)
      }
      if (hit > 0) {
        last = index
        anchor = hit
      }
    })

    const spoken = rows
      .filter(row => row.seq > anchor && row.role !== 'tool')
      .map(row => row.text.replace(/\s+/g, ''))
      .filter(text => text !== '')
    const isSame = (left: string, right: string): boolean => {
      const [short, long] = left.length <= right.length ? [left, right] : [right, left]

      return short === long || (short.length >= 12 && long.includes(short))
    }
    // From the end: the first message found is the last known one, and nothing before it matters.
    for (let index = messages.length - 1; index > last; index -= 1) {
      const text = (messages[index]?.text ?? '').replace(/\s+/g, '')
      if (text !== '' && spoken.some(row => isSame(text, row))) {
        last = index
        break
      }
    }

    return last + 1
  }

  /**
   * Files the part of a conversation the mod has no rows for: all of a session
   * that predates the mod, or just the tail added while the mod was off or a
   * hook missed a row. Rows already on disk are recognised, so a repeated call
   * files nothing and the numbering every file rests on is never disturbed.
   */
  const importMessages = async (messages: readonly ImportedMessage[]): Promise<number> => {
    await ensureLoaded()
    // With history on disk only the tail the mod has not seen is filed; with none, everything is.
    const from = state.seq === 0 ? 0 : firstUnrecorded(messages)

    let imported = 0
    for (const message of messages.slice(from)) {
      if (message.text.trim() !== '') {
        // A row that only carries the engine's reminder is nobody's request: the
        // head has to be stripped before the person check, and something has to
        // be left of it.
        const stripped = stripInjected(message.text)
        await record(
          message.role === 'user'
            ? {
                uuid: '',
                role: 'user',
                ...(stripped !== '' && looksLikePerson(stripped) ? { isPerson: true as const } : {}),
                text: message.text,
              }
            : { uuid: '', role: 'assistant', text: message.text },
        )
        imported += 1
      }
      if (message.role !== 'assistant') continue
      for (const use of message.toolUses) {
        // A call still in flight carries no text: nothing was answered, nothing to file.
        if (typeof use.text !== 'string') continue
        const input = asInput(use.input)
        const path = pathOf(input)
        const isError = use.isError === true
        const row = await record({
          uuid: '',
          role: 'tool',
          tool: use.tool,
          ...(path === undefined ? {} : { path }),
          ...(use.brief === undefined ? {} : { input: use.brief }),
          ...(use.args === undefined ? {} : { args: use.args }),
          ...(use.callId === undefined ? {} : { callId: use.callId }),
          ...(isError ? { isError: true as const } : {}),
          text: use.text,
        })
        activity(use.tool, input, row.seq, isError)
        imported += 1
      }
    }
    // The rows went through the queue; the meta is saved last, so a reader that
    // sees the new `seq` also sees the activities that came with it. An empty
    // import writes nothing at all, so a session with no history stays untouched.
    if (imported > 0) saveMeta()

    return imported
  }

  const noteRequest = (): void => {
    state.requestsSinceSwitch += 1
    state.lastRequestAt = io.now()
    // Kept on disk: a session reopened after a restart must still know how long its cache has been idle.
    saveMeta()
  }

  /**
   * The boundary sentence. The reminder and the ledger's "nothing is open any more"
   * hint share it and its flag, so a task boundary is announced once, not twice.
   */
  const boundaryReminder = (env: Env): string | null => {
    if (env.tokens === undefined) return null
    if (state.reminded.boundary || state.reminded.soft || state.reminded.urgent) return null
    state.reminded.boundary = true

    return `上下文已用 ${k(env.tokens)}k/${k(env.limit)}k。如果当前任务刚告一段落（刚完成一项、刚交付结果或在等用户回复），现在换窗口最划算：先把进度写进账本，再调用 context 工具换窗口。如果正在任务中间，就继续，不用理会。`
  }

  const reminder = (env: Env): string | null => {
    if (env.tokens === undefined) return null
    const level = levelOf(env.tokens, env.limit, config)

    if (level === 'boundary') return boundaryReminder(env)

    if (level === 'soft') {
      if (state.reminded.soft || state.reminded.urgent) return null
      state.reminded.soft = true
      state.reminded.boundary = true

      return `上下文已用 ${k(env.tokens)}k/${k(env.limit)}k，再过一段就该换窗口了。请边做边把进度写进账本，到下一个任务边界就换窗口。`
    }

    if (level !== 'urgent' || state.reminded.urgent) return null
    // Urgent carries the whole instruction itself, so a skipped soft is never sent late.
    state.reminded.urgent = true
    state.reminded.soft = true
    state.reminded.boundary = true
    const left = Math.max(0, k(env.limit - env.tokens))

    return `上下文已用 ${k(env.tokens)}k/${k(env.limit)}k，离上限只剩约 ${left}k。请现在开始准备换窗口：1）为每个未完成的任务追加账本记录，写明 next_step 和 anchors；2）把已完成的任务标为 done 并附证据；3）调用 context 工具（action: "new"）。`
  }

  const ledgerAppend = async (input: unknown, env: Env): Promise<ToolResult> => {
    await ensureLoaded()
    if (typeof input !== 'object' || input === null || Array.isArray(input)) {
      return errorOf('ledger_append 的输入必须是一个对象，至少包含 task_id、title、status、text 四个字段。')
    }
    const raw = input as Record<string, unknown>
    if (typeof raw.text !== 'string') return errorOf('text 必须是字符串，请用一句话说明这一步的要点。')

    const candidate: LedgerInput = {
      task_id: raw.task_id as string,
      title: raw.title as string,
      status: raw.status as TaskStatus,
      text: raw.text,
    }
    if (typeof raw.next_step === 'string') candidate.next_step = raw.next_step
    if (Array.isArray(raw.anchors)) candidate.anchors = raw.anchors as Anchor[]
    if (Array.isArray(raw.evidence)) candidate.evidence = raw.evidence as number[]
    if (typeof raw.superseded_by === 'string') candidate.superseded_by = raw.superseded_by
    if (typeof raw.request_ref === 'number') candidate.request_ref = raw.request_ref

    const files = new Map<string, string>()
    const absent = new Set<string>()
    for (const anchor of candidate.anchors ?? []) {
      if (typeof anchor !== 'object' || anchor === null) continue
      const path = typeof anchor.path === 'string' ? anchor.path.trim() : ''
      if (path === '') continue
      const key = pathKey(path)
      if (files.has(key) || absent.has(key)) continue
      const text = await readText(path)
      if (text === null) absent.add(key)
      else files.set(key, text)
    }
    const checkAnchor = (anchor: Anchor): AnchorCheck => {
      const path = typeof anchor.path === 'string' ? anchor.path : ''
      const text = files.get(pathKey(path))
      if (text === undefined) return 'missing-file'

      return locate(text, typeof anchor.match === 'string' ? anchor.match : '').kind
    }

    const referenced: number[] = []
    if (typeof candidate.request_ref === 'number') referenced.push(candidate.request_ref)
    if (candidate.evidence !== undefined) referenced.push(...candidate.evidence)
    await ensureHistory(referenced)

    const latest = latestPersonRow()
    const latestPersonSeq = latest === null ? null : latest.seq
    const latestRelaySeq = latestRelayRow()?.seq ?? null
    const problems = validate(candidate, {
      entries: state.page,
      history: seq => bySeq(seq),
      latestPersonSeq,
      latestRelaySeq,
      checkAnchor,
      config,
    })
    if (problems.length > 0) {
      return errorOf(`账本记录未通过校验：\n- ${problems.join('\n- ')}`)
    }

    // An omitted next_step or anchors is stored as omitted: tasksOf reads it as "unchanged" and says which entry it came from.
    const seq = state.ledgerSeq + 1
    const entry = stamp(candidate, {
      seq,
      ts: io.now(),
      window: state.window,
      latestPersonSeq,
      latestRelaySeq,
      through: state.seq,
    })
    state.ledgerSeq = seq
    state.page.push(entry)
    const ledgerWrite = queue.push(pathIn('ledger.jsonl'), toJsonl(state.page))
    saveMeta()
    const isWritten = await ledgerWrite

    // The row it was bound to is said back, so a default that picked the wrong request is seen at once.
    const bound = entry.request_ref > 0 ? bySeq(entry.request_ref) : undefined
    const boundKind = bound === undefined ? '' : bound.isPerson === true ? '用户消息' : '转交'
    const isDefault = candidate.request_ref === undefined
    let result = `已记录 #L${seq}。`
    result +=
      bound === undefined
        ? '没有可对应的请求（request_ref 记为 0）。'
        : `对应请求 #${bound.seq}（${boundKind}${isDefault ? '，省略 request_ref 时取最近一条' : ''}）。`
    // Not an error: the entry is in memory, and an error would make the model record it twice.
    if (!isWritten) {
      result += '\n注意：账本这次没能写进磁盘（内存里有，本会话内仍然有效）；下次记账会重写整个文件。'
    }
    const stillOpen = tasksOf(state.page).some(task => task.status === 'in_progress')
    if (
      entry.status === 'done' &&
      !stillOpen &&
      env.tokens !== undefined &&
      levelOf(env.tokens, env.limit, config) === 'boundary'
    ) {
      // The same sentence the reminder gives at this fill: whichever comes first says it.
      const said = boundaryReminder(env)
      if (said !== null) result += `\n${said}`
    }

    return { result }
  }

  const renderEntry = (entry: LedgerEntry): string => {
    const parts = [entry.task_id, STATUS_LABEL[entry.status], entry.title, entry.text]
    if (entry.next_step !== undefined && entry.next_step.trim() !== '') parts.push(`下一步：${entry.next_step}`)
    if (Array.isArray(entry.evidence) && entry.evidence.length > 0) {
      parts.push(`证据：${entry.evidence.map(seq => `#${seq}`).join('、')}`)
    }
    if (entry.superseded_by !== undefined && entry.superseded_by !== '') {
      parts.push(`由 ${entry.superseded_by} 取代`)
    }

    return `#L${entry.seq} · ${parts.join(' · ')}`
  }

  const renderEntries = (entries: readonly LedgerEntry[]): string =>
    entries.length === 0 ? '账本里还没有条目。' : entries.map(renderEntry).join('\n')

  const queryLedger = async (query: string): Promise<string> => {
    const needle = query.toLowerCase()
    const matches = (entry: LedgerEntry): boolean => {
      const fields: unknown[] = [entry.task_id, entry.title, entry.text, entry.next_step ?? '']
      return fields.some(field => typeof field === 'string' && field.toLowerCase().includes(needle))
    }
    const all: LedgerEntry[] = [...state.page]
    for (let page = 1; page <= state.archive.length; page += 1) {
      const entries = await loadArchive(page)
      if (entries !== null) all.push(...entries)
    }
    const hits = all.filter(matches).slice(0, MAX_QUERY_HITS)

    return hits.length === 0 ? `没有匹配「${query}」的账本条目。` : hits.map(renderEntry).join('\n')
  }

  const ledgerRead = async (input: unknown): Promise<ToolResult> => {
    await ensureLoaded()
    const raw =
      typeof input === 'object' && input !== null && !Array.isArray(input)
        ? (input as Record<string, unknown>)
        : {}
    const view = typeof raw.view === 'string' && raw.view.trim() !== '' ? raw.view.trim() : 'home'
    const query = typeof raw.query === 'string' && raw.query.trim() !== '' ? raw.query.trim() : null
    if (query !== null) return { result: await queryLedger(query) }

    if (view === 'home') {
      await ensureRequests()
      await ensureAnswered()
      const relay = await relayForHome()
      const rows = allRows()
      const requests = personRequests(rows, config.recentRequests)

      return {
        result: renderHome(
          {
            window: state.window,
            entries: state.page,
            requests: displayRequests(requests),
            ...(relay === undefined ? {} : { relay }),
            answered: repliesAnswered(rows, requests),
            archive: state.archive,
          },
          config,
        ),
      }
    }
    if (view === 'current') return { result: renderEntries(state.page) }

    const archive = /^archive:(\d+)$/.exec(view)
    if (archive !== null) {
      const page = Number(archive[1] ?? '')
      if (!Number.isInteger(page) || page < 1) return errorOf(`archive 的页号必须是正整数，收到的是「${view}」。`)
      const entries = await loadArchive(page)
      if (entries === null) {
        return errorOf(
          failedWrites.has(pathIn(archiveName(page)))
            ? `归档页 archive:${page} 读不到：归档页文件缺失，那次写入没有落盘。`
            : `没有找到归档页 archive:${page}。`,
        )
      }

      return { result: renderEntries(entries) }
    }

    return errorOf(`view 只能是 home、current 或 archive:N，收到的是「${view}」。`)
  }

  const renderHit = (hit: SearchHit): string =>
    `#${hit.seq} w${hit.window} ${hit.role}${
      hit.door === undefined ? '' : ` <${hit.door}${hit.name === undefined ? '' : `/${hit.name}`}>`
    }${hit.tool === undefined ? '' : ` [${hit.tool}]`}${
      hit.input === undefined ? '' : ` ${hit.input}`
    }${hit.path === undefined ? '' : ` [${hit.path}]`}：${hit.excerpt}${
      hit.overflow === undefined
        ? ''
        : ` [overflow ${hit.overflow.field === 'args' ? 'input' : 'text'} offset=${hit.overflow.offset}]`
    }`

  const historySearch = async (raw: Record<string, unknown>): Promise<ToolResult> => {
    const problems: string[] = []
    const windowField = raw.window
    if (
      windowField !== undefined &&
      (typeof windowField !== 'number' || !Number.isInteger(windowField) || windowField < 1)
    ) {
      problems.push('window 必须是大于等于 1 的整数。')
    }
    const roleField = raw.role
    if (roleField !== undefined && roleField !== 'user' && roleField !== 'assistant' && roleField !== 'tool') {
      problems.push('role 只能是 user、assistant 或 tool 之一。')
    }
    for (const name of ['query', 'tool_name', 'path', 'door'] as const) {
      if (raw[name] !== undefined && typeof raw[name] !== 'string') problems.push(`${name} 必须是字符串。`)
    }
    if (raw.limit !== undefined && (typeof raw.limit !== 'number' || !Number.isInteger(raw.limit) || raw.limit < 0)) {
      problems.push('limit 必须是非负整数。')
    }
    if (problems.length > 0) return errorOf(`history 的输入有问题：\n- ${problems.join('\n- ')}`)

    // A part that is gone or damaged is skipped by the search; the person still has to
    // learn that this answer is not the whole history, so each failure is said once.
    const overflowProblems: string[] = []
    const seenOverflowProblems = new Set<string>()
    const noteOverflowFailure = (failure: OverflowFailure): void => {
      const key = `${failure.seq}:${failure.field}:${failure.part}`
      if (seenOverflowProblems.has(key)) return
      seenOverflowProblems.add(key)
      const field = failure.field === 'args' ? 'input' : 'text'
      const why =
        failure.reason === 'missing'
          ? '文件缺失'
          : failure.reason === 'unreadable'
            ? '读取失败'
            : `内容被截短（${failure.actual ?? '?'}/${failure.expected ?? '?'} 字符）`
      overflowProblems.push(`#${failure.seq} 的 overflow ${field} 第 ${failure.part} 段${why}，已跳过`)
    }
    const withOverflowNotes = (text: string): string =>
      overflowProblems.length === 0 ? text : `${text}\n（${overflowProblems.join('；')}）`

    const target = windowField as number | undefined
    const searchIn = async (windows: readonly number[]): Promise<SearchHit[]> => {
      for (const window of windows) await loadWindow(window)
      const wanted = new Set(windows)
      // An overflow part queued a moment ago is not on disk yet. A search reads one only
      // for a row that missed inline, so this costs an ordinary search nothing.
      await queue.idle()

      return search(
        allRows().filter(row => wanted.has(row.window)),
        {
          query: typeof raw.query === 'string' ? raw.query : '',
          window: target,
          role: raw.role as Role | undefined,
          tool: typeof raw.tool_name === 'string' ? raw.tool_name : undefined,
          path: typeof raw.path === 'string' ? raw.path : undefined,
          door: typeof raw.door === 'string' ? raw.door : undefined,
          limit: raw.limit as number | undefined,
        },
        async (seq, field, part) => {
          const path = pathIn(overflowName(seq, field, part))

          return failedWrites.get(path) ?? (await readText(path))
        },
        { onOverflowError: noteOverflowFailure },
      )
    }

    if (target !== undefined) {
      const found = await searchIn([target])

      return {
        result: withOverflowNotes(
          found.length === 0 ? `第 ${target} 个窗口里没有匹配（只搜了这个窗口）。` : found.map(renderHit).join('\n'),
        ),
      }
    }

    // A miss in the recent windows does not mean it never happened, so older ones are added one at a time until something hits.
    let first = Math.max(1, state.window - SEARCH_WINDOWS + 1)
    const recent: number[] = []
    for (let window = first; window <= state.window; window += 1) recent.push(window)
    let hits = await searchIn(recent)
    while (hits.length === 0 && first > 1) {
      first -= 1
      hits = await searchIn([first])
    }

    const span = (from: number, to: number): string => (from === to ? `第 ${from} 个窗口` : `第 ${from}–${to} 个窗口`)
    if (hits.length === 0) {
      return { result: withOverflowNotes(state.window === 1 ? '没有匹配。' : `${span(1, state.window)}里都没有匹配。`) }
    }
    const body = hits.map(renderHit).join('\n')
    if (first === 1) return { result: withOverflowNotes(body) }

    return { result: withOverflowNotes(`${body}\n（搜了${span(first, state.window)}；${span(1, first - 1)}没搜，要搜用 window 指定）`) }
  }

  const historyRead = async (raw: Record<string, unknown>): Promise<ToolResult> => {
    const problems: string[] = []
    const seqField = raw.seq
    if (seqField === undefined || typeof seqField !== 'number' || !Number.isInteger(seqField)) {
      problems.push('seq 必须是整数：用 history search 查到的历史编号。')
    }
    for (const name of ['offset', 'length'] as const) {
      if (raw[name] !== undefined && (typeof raw[name] !== 'number' || !Number.isInteger(raw[name]) || raw[name] < 0)) {
        problems.push(`${name} 必须是非负整数。`)
      }
    }
    if (raw.field !== undefined && raw.field !== 'text' && raw.field !== 'input') {
      problems.push('field 只能是 text（结果正文，默认）或 input（调用参数全文）。')
    }
    if (problems.length > 0) return errorOf(`history 的输入有问题：\n- ${problems.join('\n- ')}`)

    const seq = seqField as number
    const offset = typeof raw.offset === 'number' ? raw.offset : 0
    const length = typeof raw.length === 'number' ? raw.length : undefined
    const field = raw.field === 'input' ? 'input' : 'text'
    const readAt = (): ReturnType<typeof readRecord> => {
      const rows = allRows()

      return length === undefined ? readRecord(rows, seq, offset, undefined, field) : readRecord(rows, seq, offset, length, field)
    }

    let result = readAt()
    for (let window = state.window - 1; !result.found && window >= 1; window -= 1) {
      await loadWindow(window)
      result = readAt()
    }
    if (!result.found) return errorOf(`历史里没有 #${seq} 这条记录。`)

    let { text, total, hasMore } = result
    const notes: string[] = result.note === undefined ? [] : [result.note]
    if (result.overflow !== undefined) {
      const whole = await readOverflow(result.seq, result.field === 'input' ? 'args' : 'text', result.overflow, offset, length)
      if (whole === null) {
        // Never pass the row's head off as the whole: the reader must know the rest was lost.
        notes.push('这一段原文没有写进磁盘，下面只有行内保存的开头，不是全文。')
      } else {
        text = whole.text
        total = whole.total
        hasMore = whole.hasMore
      }
    }

    const header = `#${result.seq} w${result.window} ${result.role}${
      result.tool === undefined ? '' : ` [${result.tool}]`
    }${result.path === undefined ? '' : ` [${result.path}]`}${result.field === 'input' ? ' 调用参数' : ''} 共 ${total} 字符${
      hasMore ? '，还有后续，用 offset 继续读' : ''
    }`

    return { result: `${[header, ...notes].join('\n')}\n${text}` }
  }

  /**
   * One slice of a field whose whole original lives in the overflow files, or null when a part
   * it needs cannot be had. A part whose write failed is still in memory and serves the read.
   */
  const readOverflow = async (
    seq: number,
    field: 'text' | 'args',
    overflow: Overflow,
    offset: unknown,
    length: unknown,
  ): Promise<{ text: string; total: number; hasMore: boolean } | null> => {
    // A part queued a moment ago is not on disk yet.
    await queue.idle()
    const { start, end } = sliceBounds(overflow.chars, offset, length)
    const wanted = start < end ? partsCovering(overflow, start, end) : []
    let joined = ''
    for (const part of wanted) {
      const path = pathIn(overflowName(seq, field, part))
      const text = failedWrites.get(path) ?? (await readText(path))
      if (text === null) return null
      joined += text
    }
    const origin = wanted.length === 0 ? 0 : partOrigin(overflow, wanted[0] ?? 0)
    const slice = wanted.length === 0 ? '' : joined.slice(start - origin, end - origin)
    // A part cut short on disk would hand back a slice that is not what the offset names.
    if (slice.length !== Math.max(0, end - start)) return null

    return { text: slice, total: overflow.chars, hasMore: end < overflow.chars }
  }

  const historyTool = async (input: unknown): Promise<ToolResult> => {
    await ensureLoaded()
    const raw =
      typeof input === 'object' && input !== null && !Array.isArray(input)
        ? (input as Record<string, unknown>)
        : {}
    if (raw.action !== 'search' && raw.action !== 'read') {
      return errorOf('history 工具需要 action："search" 或 "read"。')
    }

    return raw.action === 'search' ? historySearch(raw) : historyRead(raw)
  }

  const status = (env: Env): string => {
    const now = io.now()
    const switches = state.switchTimes.filter(at => at > now - 3_600_000 && at <= now).length
    const open = tasksOf(state.page).filter(task => task.status === 'in_progress').length

    const unwritten = unsaved()

    return `${describeFill(env.tokens, env.limit, state.window)} · 距上次换窗口 ${state.requestsSinceSwitch} 次请求 · 本小时已换窗口 ${switches} 次 · 进行中任务 ${open} 个${unwritten.length === 0 ? '' : ` · 有 ${unwritten.length} 个文件没写进磁盘`}`
  }

  /** One line of the write-amplification counters; process-local and never persisted. */
  const historyWriteStats = (): string => {
    const kb = (bytes: number): string => (bytes / 1024).toFixed(1)
    const waf =
      writeStats.logicalNewBytes === 0
        ? '0.00'
        : (writeStats.physicalBytesWritten / writeStats.logicalNewBytes).toFixed(2)
    const merged = writeStats.coalesced === 0 ? '' : `，合并 ${writeStats.coalesced} 次`

    return `history 写入：逻辑 ${kb(writeStats.logicalNewBytes)} KB / 实际 ${kb(writeStats.physicalBytesWritten)} KB（WAF=${waf}），写盘 ${writeStats.writeCalls} 次${merged}`
  }

  /** Whether the current page of the ledger carries an entry made after the latest person prompt. */
  const isLedgerFresh = (): boolean => {
    const latest = latestPersonRow()

    return hasFreshEntry(state.page, latest === null ? 0 : latest.ts, state.window)
  }

  /**
   * The work done after the window's latest ledger entry: tool results of the main conversation
   * (this mod's own calls are not work) that the entry did not cover. An entry from before
   * `through` existed is compared by time instead of by history number.
   */
  const tailOf = (): { steps: number; from: number | null; to: number | null; entrySeq: number | null } => {
    let latest: LedgerEntry | null = null
    for (const entry of state.page) {
      if (entry.window === state.window && (latest === null || entry.seq > latest.seq)) latest = entry
    }
    const covered = latest
    let steps = 0
    let from: number | null = null
    let to: number | null = null
    for (const row of allRows()) {
      if (row.window !== state.window || row.role !== 'tool' || row.door !== undefined || isOwnRow(row)) continue
      if (covered !== null) {
        const isCovered = typeof covered.through === 'number' ? row.seq <= covered.through : row.ts <= covered.ts
        if (isCovered) continue
      }
      steps += 1
      if (from === null || row.seq < from) from = row.seq
      if (to === null || row.seq > to) to = row.seq
    }

    return { steps, from, to, entrySeq: covered === null ? null : covered.seq }
  }

  /** Whether a compaction can leave the summary to the ledger: it is fresh and little happened since. */
  const canSkipSummary = (): boolean => isLedgerFresh() && tailOf().steps <= config.autoTailSteps

  /**
   * Holds back a ToolSearch that would load a costly group, once the context is past the gate:
   * the model is sent to record its progress and switch first, and the load waits for the new
   * window. A group is held back once per window, so a repeat goes through and a refused switch
   * cannot stall the session. A group this window already loaded is not held back again.
   */
  const gateLoad = (query: unknown, tokens: number | undefined): string | null => {
    if (typeof query !== 'string' || tokens === undefined || tokens <= config.gateMinTokens) return null
    const costly = costlyGroups()
    const named = groupsWanted(query, Object.keys(costly))
    if (named.length === 0) return null
    const loadedHere = new Set<string>()
    for (const row of allRows()) {
      if (row.window !== state.window || row.tool !== 'ToolSearch' || row.loaded === undefined) continue
      for (const name of row.loaded) loadedHere.add(toolGroupOf(name))
    }
    const wanted = named.filter(group => !loadedHere.has(group) && !state.gateAsked.includes(group))
    if (wanted.length === 0) return null

    state.gateAsked = [...state.gateAsked, ...wanted]
    state.gateWanted = [...new Set([...state.gateWanted, ...wanted])]
    const names = wanted.join('、')
    const biggest = Math.max(...wanted.map(group => costly[group] ?? 0))

    return `先不加载：加载 ${names} 会让整段对话的缓存重建（上次加载后重写了${rewriteOf(biggest)} token），当前上下文 ${k(tokens)}k。请先用 ledger_append 把进度记进账本，next_step 写明“换窗后第一步用 ToolSearch 加载 ${names}”，然后调用 context 工具（action: "new"），在新窗口里加载。如果换窗口被拒绝，或者只差这一步就做完，再调用一次 ToolSearch 即可照常加载。`
  }

  const requestSwitch = (input: unknown, env: Env): ToolResult => {
    // An approval already stands: asking again changes nothing, and re-stamping it
    // would only stretch the time the model has to end the turn.
    if (pending() !== null) return { result: APPROVED }

    const raw =
      typeof input === 'object' && input !== null && !Array.isArray(input)
        ? (input as Record<string, unknown>)
        : {}
    const reason = typeof raw.reason === 'string' ? raw.reason : ''
    const now = io.now()
    const judgement = judgeSwitch(
      {
        before: env.tokens ?? 0,
        prefix: state.lastPrefix ?? DEFAULT_PREFIX,
        handoff: state.lastHandoff ?? DEFAULT_HANDOFF,
        reread: config.snippetTokens,
        remainingRequests: raw.expect_more_work === false ? REMAINING_REQUESTS_LAST : REMAINING_REQUESTS,
      },
      config,
    )
    const isFresh = isLedgerFresh()
    const tail = tailOf()
    const isTailShort = tail.steps <= config.freshTailSteps
    let staleReason: string | undefined
    if (!isFresh) {
      staleReason = '账本还不新：这个窗口里在最近一次用户请求之后还没有记过账。'
    } else if (!isTailShort) {
      const range = tail.from === null || tail.to === null ? '' : `（#${tail.from}–#${tail.to}）`
      staleReason = `账本还不新：最近一次记账（#L${tail.entrySeq ?? 0}）之后又有 ${tail.steps} 个工具结果没有记进账本${range}。`
    }
    const gate = gateSwitch(
      {
        requestsSinceSwitch: state.requestsSinceSwitch,
        switchTimes: state.switchTimes,
        now,
        hasFreshLedger: isFresh && isTailShort,
        ...(staleReason === undefined ? {} : { staleReason }),
        level: env.tokens === undefined ? 'none' : levelOf(env.tokens, env.limit, config),
        judgement,
        // A switch made in front of a held-back load may skip the cooldown and the payoff.
        isForLoad: state.gateWanted.length > 0,
      },
      config,
    )
    if (!gate.isAllowed) return errorOf(`暂不换窗口：${gate.reason}`)

    state.pending = { reason, at: now, requests: state.requestsSinceSwitch, seq: state.seq }

    return { result: APPROVED }
  }

  const pending = (): Pending | null => {
    if (state.pending === null) return null
    if (io.now() - state.pending.at > PENDING_MS) {
      state.pending = null

      return null
    }

    return state.pending
  }

  /**
   * Whether a tool call must be refused because a switch stands. The calls sent in the
   * same step as the approved `new` still run, so finished edits can ride along with the
   * switch; only a call from a later step, which the model was told not to make, is refused.
   */
  const blocksCalls = (): boolean => {
    const p = pending()

    return p !== null && state.requestsSinceSwitch > p.requests
  }

  const clearPending = (): void => {
    state.pending = null
  }

  const buildHandoff = async (opts: { isMidTurn: boolean; agents?: readonly AgentNote[] }): Promise<string> => {
    await ensureLoaded()
    await ensureRequests()
    await ensureReplies()
    await ensureAnswered()
    const relay = await relayForHome()
    const rows = allRows()
    const requests = displayRequests(personRequests(rows, config.recentRequests))
    const answered = repliesAnswered(rows, requests)
    const window = state.window + 1
    const agents = renderAgents(agentsForHandoff(opts.agents ?? [], state.roster, io.now(), config))
    const home = renderHome(
      { window, entries: state.page, requests, ...(relay === undefined ? {} : { relay }), answered, archive: state.archive },
      config,
    )
    // A running task is already spelled out in the home page: repeating the last
    // reply beside it would only spend the handoff's budget twice on the same turn.
    const running = tasksOf(state.page).some(task => task.status === 'in_progress')
    const lastReply = running ? null : lastReplyOf()
    const open: TaskState[] = tasksOf(state.page)
      .filter(task => task.status === 'in_progress' || task.status === 'blocked')
      .sort((left, right) => right.latest.ts - left.latest.ts || right.latest.seq - left.latest.seq)
    const tasks: OpenTask[] = open.map(task => ({ taskId: task.taskId, anchors: task.anchors?.value ?? [] }))
    const inherited = new Map<string, number>()
    for (const task of open) {
      if (task.anchors?.isInherited === true) inherited.set(task.taskId, task.anchors.seq)
    }

    const files = new Map<string, FileContent>()
    for (const path of pathsToRead(tasks, state.activities, state.window)) {
      const key = pathKey(path)
      if (files.has(key)) continue
      try {
        files.set(key, await io.read(path))
      } catch (problem) {
        files.set(key, messageOf(problem).includes('ENOENT') ? { missing: true } : { tooLarge: true })
      }
    }

    const snippets = snippetsOf(
      { tasks, files, activities: state.activities, window: state.window },
      config,
    )
    // Only the text the model reads is shortened: the activities, meta and shards keep absolute paths.
    let base: string | undefined
    try {
      base = (await io.cwd?.()) || undefined
    } catch {
      // No working directory known: the paths are shown as they are.
    }
    const workset = renderWorkset(filesOf(state.activities, state.window), snippets, inherited, base)
    const tail = tailOf()
    // The whole uncovered stretch is listed (up to a cap), since the ledger holds nothing of it.
    const actions = recentActions(
      rows,
      state.window,
      Math.max(config.recentActions, Math.min(MAX_TAIL_ACTIONS, tail.steps)),
      state.pending?.seq,
    ).map(action => (action.path === undefined ? action : { ...action, path: relativePath(action.path, base) }))
    const coverage = renderCoverage(tail)
    const tools = renderTools(costlyToolsOf(loadedTools(rows, state.window), costlyGroups()))
    const loadReason = renderLoadReason(state.gateWanted)

    return assemble(
      {
        window,
        home,
        workset,
        actions,
        isMidTurn: opts.isMidTurn,
        ...(loadReason === '' ? {} : { loadReason }),
        ...(coverage === '' ? {} : { coverage }),
        ...(agents === '' ? {} : { agents }),
        ...(tools === '' ? {} : { tools }),
        ...(lastReply === null ? {} : { lastReply }),
      },
      config,
    )
  }

  const commitSwitch = async (info: {
    trigger: string
    tokensBefore: number | undefined
    handoffText: string
  }): Promise<void> => {
    await ensureLoaded()
    await ensureRequests()
    const now = io.now()
    if (eventsText === null) eventsText = (await readText(pathIn('events.jsonl'))) ?? ''
    const event = {
      at: now,
      window: state.window,
      trigger: info.trigger,
      reason: state.pending === null ? null : state.pending.reason,
      tokensBefore: info.tokensBefore ?? null,
      handoffTokens: estimateTokens(info.handoffText),
      requestsSinceSwitch: state.requestsSinceSwitch,
    }
    // Kept beside the history so a person can read what each window opened with.
    void queue.push(
      pathIn(handoffName(state.window + 1)),
      info.handoffText,
    )
    eventsText = `${eventsText}${JSON.stringify(event)}\n`
    void queue.push(pathIn('events.jsonl'), eventsText)

    const requests = personRequests(allRows(), config.recentRequests)
    const requestSeqs = new Set(requests.map(row => row.seq))
    const protectedIds = new Set(
      state.page.filter(entry => requestSeqs.has(entry.request_ref)).map(entry => entry.task_id),
    )
    const { moved } = turnPage(state.page, protectedIds, config)
    if (moved.length > 0) {
      const page = state.archive.length + 1
      const archivePath = pathIn(archiveName(page))
      // The entries leave the ledger only once their page is on disk; otherwise they would survive in memory alone.
      const isArchived = await queue.push(archivePath, toJsonl(moved))
      if (!isArchived) {
        // This attempt is abandoned and the next switch rebuilds the page, so a retry of the stale text must not land.
        failedWrites.delete(archivePath)
      } else if (state.archive.length + 1 === page) {
        state.archive.push(pageOf(page, moved))
        // Entries recorded while the page was being written stay: only the archived ones leave.
        const movedSeqs = new Set(moved.map(entry => entry.seq))
        state.page = state.page.filter(entry => !movedSeqs.has(entry.seq))
        void queue.push(pathIn('ledger.jsonl'), toJsonl(state.page))
      }
    }

    saveManifest(state.window)
    state.window += 1
    state.part = 0
    state.requestsSinceSwitch = 0
    state.reminded = { boundary: false, soft: false, urgent: false }
    state.switchTimes = [...state.switchTimes, now].filter(at => at > now - 3_600_000)
    state.lastHandoff = estimateTokens(info.handoffText)
    state.pending = null
    // The new window's first request has no earlier context to judge a load against.
    state.lastContext = null
    state.pendingLoads = []
    // The gate's memory is per window: the new one may hold back its own loads again.
    state.gateAsked = []
    state.gateWanted = []


    fullWindows.add(state.window)
    saveMeta()
  }

  const notePrefix = (tokens: number): void => {
    state.lastPrefix = Math.max(0, tokens - (state.lastHandoff ?? 0))
  }

  const flush = async (): Promise<void> => {
    await ensureLoaded()
    await queue.idle()
    if (failedWrites.size === 0) return
    // Only with the queue empty: a queued newer text for the same path would be overwritten by the old one.
    for (const [path, text] of [...failedWrites]) void queue.push(path, text)
    await queue.idle()
  }

  // Only this session's own files: the cross-session table sits outside the directory, and a
  // new window never needs it to pick the work up.
  const hold = async (text: string): Promise<number | null> => {
    await ensureLoaded()
    const id = held.reduce((top, item) => Math.max(top, item.id), 0) + 1
    held = [...held, { id, text, at: io.now() }]
    const isWritten = await queue.push(pathIn(HELD_FILE), heldJson())
    if (isWritten) return id

    // Not on disk, so the message must not be held: it goes in as usual. The failed text
    // would come back from a flush retry otherwise, with this item in it.
    held = held.filter(item => item.id !== id)
    failedWrites.delete(pathIn(HELD_FILE))

    return null
  }

  const heldItems = (): HeldItem[] => held.map(item => ({ ...item }))

  const release = async (id: number): Promise<void> => {
    await ensureLoaded()
    if (!held.some(item => item.id === id)) return
    held = held.filter(item => item.id !== id)
    // A failed write is left to flush's retry; the item is delivered either way.
    await queue.push(pathIn(HELD_FILE), heldJson())
  }

  const unsaved = (): string[] =>
    [...failedWrites.keys()]
      .filter(path => path.startsWith(`${root}/`))
      .map(path => path.slice(root.length + 1))
      .sort()

  const latestPersonSeq = (): number | null => {
    const latest = latestPersonRow()

    return latest === null ? null : latest.seq
  }

  const latestRelaySeq = (): number | null => latestRelayRow()?.seq ?? null

  return {
    record,
    activity,
    noteAgent,
    agentEnded,
    agentStep,
    agentResumed,
    coldResend,
    noteStep,
    costlyGroups,
    importMessages,
    noteRequest,
    reminder,
    ledgerAppend,
    ledgerRead,
    historyTool,
    historyWriteStats,
    status,
    blocksCalls,
    requestSwitch,
    gateLoad,
    ready,
    pending,
    clearPending,
    buildHandoff,
    commitSwitch,
    notePrefix,
    window: () => state.window,
    flush,
    unsaved,
    hold,
    heldItems,
    release,
    latestPersonSeq,
    latestRelaySeq,
    isLedgerFresh,
    canSkipSummary,
    lastRequestAt: () => state.lastRequestAt,
  }
}

